function nextWord(){const f=filt(),pool=f,ret=w=>(lastW=w,w);
if(rvAll){const c=pool.filter(w=>w!==lastW),a=c.length?c:pool;return ret(a[Math.floor(Math.random()*a.length)])}
const fromRQ=x=>{RQ=RQ.filter(y=>y!==x);const s=S.sr[key(x.w)];if(s)s.due=0;return ret(x.w)};
const r=RQ.find(x=>x.n<=0&&x.w!==lastW&&pool.includes(x.w));if(r)return fromRQ(r);
const d=pool.filter(w=>due(w)&&w!==lastW),nw=pool.filter(w=>isNewW(w)&&w!==lastW);
if(!d.length&&!nw.length){const q=RQ.find(x=>pool.includes(x.w));if(q)return fromRQ(q);
const left=pool.filter(w=>due(w)||isNewW(w));return left.length?ret(left[0]):null}
RQ.forEach(x=>x.n--);
const c=(d.length&&(Math.random()<.6||!nw.length))?d:nw;
return ret(c[Math.floor(Math.random()*c.length)])}
const trs=w=>w.tr.split(/[,;\/]/).map(nz).filter(Boolean);
function dPool(w){const L=LO[w.l]||2,a=words.filter(x=>x.p===w.p&&Math.abs((LO[x.l]||2)-L)<=1),s=a.length>400?shuf(a).slice(0,400):a.slice();(w.c||[]).forEach(c=>words.forEach(x=>{if(x.w===c&&!s.includes(x))s.push(x)}));return s.length>=8?s:words}
function distract(w,n,fillMode){const tw=trs(w);
return dPool(w).filter(x=>x!==w&&x.w!==w.w&&!trs(x).some(t=>tw.includes(t))&&!(fillMode&&x.t===w.t)).map(x=>{let s=Math.random()*1.5;
if(x.p===w.p)s+=3;if(!fillMode&&x.t===w.t)s+=2;if(x.l===w.l)s+=.5;
const dw=dist(nz(w.w),nz(x.w));if(dw<=3)s+=3-dw;
const dt=dist(nz(w.tr),nz(x.tr));if(dt<=3)s+=2-dt/2;
if((w.c||[]).includes(x.w)||(x.c||[]).includes(w.w))s+=10;
return[s,x]}).sort((a,b)=>b[0]-a[0]).slice(0,n).map(a=>a[1])}
