function say(t,slow){if(!canSay())return;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang=S.ac==='uk'?'en-GB':'en-US';if(VO)u.voice=VO;u.rate=slow?.65:.92;speechSynthesis.speak(u)}catch(e){}}
