const GCON=[[/\bi'm\b/g,'i am'],[/\bcan't\b/g,'cannot'],[/\bwon't\b/g,'will not'],[/\bshan't\b/g,'shall not'],[/\b(\w+)'re\b/g,'$1 are'],[/\b(\w+)n't\b/g,'$1 not'],[/\b(\w+)'ve\b/g,'$1 have'],[/\b(\w+)'ll\b/g,'$1 will'],[/\bcan not\b/g,'cannot']];
function grN(s){let t=String(s).toLowerCase().replace(/[’`]/g,"'").replace(/[.,!?;:"()]/g,' ');GCON.forEach(([r,x])=>t=t.replace(r,x));return t.replace(/\s+/g,' ').trim()}
const grV=s=>{const t=grN(s),r=/\b(he|she|it|that|there|what|who|where|this|here|how|everyone|nobody)'s\b/g;return [...new Set([t,t.replace(r,'$1 is'),t.replace(r,'$1 has')])]};
function grCheck(user,answers,q,kind){const uv=grV(user);if(!uv[0])return null;
 const keys=[];answers.forEach(a=>{keys.push(...grV(a));if(q&&q.includes('___'))keys.push(...grV(q.replace(/\s*\([^)]*\)/g,'').replace('___',a)))});
 if(uv.some(u=>keys.includes(u)))return {v:'ok'};
 if(kind!=='tr')return {v:'no'};
 for(const u of uv)for(const k of keys){const a=u.split(' '),b=k.split(' ');if(a.length!==b.length)continue;let ok=true,diff=0;
  for(let i=0;i<a.length;i++){if(a[i]===b[i])continue;diff++;const L=b[i].length,m=Math.min(L,a[i].length);let p=0;while(p<m&&a[i][p]===b[i][p])p++;if(L<5||p>=m-2||dist(a[i],b[i])>(L>=8?2:1)){ok=false;break}}
  if(ok&&diff)return {v:'near'}}
 return {v:'no'}}
const GLV=['A1','A2','B1','B2','C1','C2'],GLN={A1:'Başlangıç',A2:'Temel',B1:'Orta',B2:'Orta üstü',C1:'İleri',C2:'Ustalık'};
const GS=()=>S.gr||(S.gr={});
const gUnitInfo=id=>{for(const l of GLV){const u=GSYL[l].find(x=>x[0]===id);if(u)return {id,l,t:u[1],tt:u[2]}}return null};
let GL=null,GID=null,GTAB='k',GQ=null,GALL=false,GT=null,GTS=null;
function gFixPre(t){return String(t).replace(/\s*\([^)]*\)\s*/g,' ').trim()}
const gLbl=t=>{const m=String(t).match(/\(([^)]*)\)/);return m?m[1]:''};
// ---------- türetilmiş sorular ----------
const gKey=s=>grN(s).split(' ').sort().join(' ');
const gWt=s=>String(s).toLowerCase().replace(/[’`]/g,"'").replace(/[.,!?;:"“”()]/g,'');
function gOrdFrom(prompt,answers,why){const a=String(answers[0]||'');if(!a||/[—–()\/"“”:;]/.test(a))return null;let t=a.trim(),end='';const m=t.match(/[.?!]+$/);if(m){end=m[0];t=t.slice(0,-end.length)}
 if(/[.?!]/.test(t))return null;const tk=t.split(/\s+/);if(tk.length<3||tk.length>12)return null;const k=gKey(a);return ['ord',prompt,answers.filter(x=>gKey(x)===k),why,tk,end]}
function gPickFrom(f){const w=gFixPre(f[1]),c=String(f[2][0]||'');if(/[—–\/]/.test(w+c))return null;const W=w.split(/\s+/),C=c.split(/\s+/),wn=W.map(gWt),cn=C.map(gWt);
 if(W.length===C.length){const d=[];wn.forEach((x,i)=>{if(x!==cn[i])d.push(i)});if(d.length===1)return ['pick',w,d[0],f[3],c,gLbl(f[1])]}
 if(W.length===C.length+1){for(let i=0;i<W.length;i++){const r=wn.filter((_,j)=>j!==i);if(r.join(' ')===cn.join(' '))return ['pick',w,i,f[3],c,gLbl(f[1])]}}
 return null}
const GX={};
function gAll(id){if(GX[id])return GX[id];const u=GU[id],base=u.q,fx=base.filter(q=>q[0]==='fix'),ords=[],tfs=[],picks=[],used=new Set();
 base.filter(q=>q[0]==='tr').forEach(q=>{const o=gOrdFrom(q[1],q[2],q[3]);if(o)ords.push(o)});
 u.b.filter(b=>b[0]==='eg').forEach(b=>b[1].forEach(([en,tr])=>{const o=gOrdFrom(tr,[en],'Örnek cümle konu anlatımında geçiyor.');if(o)ords.push(o)}));
 fx.forEach((f,i)=>{const p=gPickFrom(f);if(p&&picks.length<2){picks.push(p);used.add(i)}});
 fx.forEach((f,i)=>{if(used.has(i)||tfs.length>=2)return;tfs.push(['tf',gFixPre(f[1]),false,f[3],f[2][0],gLbl(f[1])])});
 const tsrc=fx.find((f,i)=>!used.has(i)&&!tfs.some(t=>t[4]===f[2][0])&&!/[—–]/.test(f[2][0]))||fx.find(f=>!/[—–]/.test(f[2][0]));if(tsrc)tfs.push(['tf',tsrc[2][0],true,tsrc[3],tsrc[2][0],gLbl(tsrc[1])]);
 if(tfs.length<3)(u.b.find(b=>b[0]==='err')||[0,[]])[1].forEach(([w,r,n])=>{if(tfs.length<3&&!/[\/()✓✗]/.test(w))tfs.push(['tf',w,false,n,r.split(' / ')[0],''])});
 const cg=[],cx=u.b.find(b=>b[0]==='ctx');if(cx){let bi=0;cx[1].x.split(/(?<=[.!?])\s+/).forEach(sn=>{const m=(sn.match(/___/g)||[]).length;if(m===1&&cg.length<2&&!/^[A-Z][a-z]*:/.test(sn))cg.push(['gap',sn,cx[1].a[bi],cx[1].n[bi]+' (Bağlamda metninden)']);bi+=m})}
 const gen=[...ords.slice(0,3),...tfs.slice(0,3),...picks.slice(0,2),...cg];
 const all=[...base,...gen],order=[];let gi=base.length;base.forEach((_,i)=>{order.push(i);if(i%2===1&&gi<all.length)order.push(gi++)});while(gi<all.length)order.push(gi++);
 return GX[id]={all,order,nb:base.length}}
function gLesson(id){const u=GU[id],secs=gSecs(u.b),g=gAll(id);let added=0;const egs=[];
 const out=secs.map(sb=>{const n=sb.filter(b=>b[0]==='ask').length,res=[];sb.forEach(b=>{res.push(b);if(b[0]==='eg'&&n<3&&added<2){const ex=b[1].map(([en,tr])=>gOrdFrom(tr,[en],'Bu cümle konu anlatımındaki örneklerden.')).filter(Boolean);const o=ex[ex.length-1];if(o){res.push(['ask',o]);added++}}});return res});
 return out}
