const QL={mc:'Doğru seçeneği seç',gap:'Boşluğu doldur',fix:'Hatayı düzelt, cümlenin doğrusunu yaz',tr:'İngilizceye çevir',ord:'Kelimeleri doğru sıraya diz',tf:'Bu cümle dilbilgisi açısından doğru mu?',pick:'Hatalı kelimeye dokun'};
const qRight=q=>{const k=q[0];return k==='mc'?q[2][q[3]]:k==='gap'?q[1].replace(/\s*\([^)]*\)/g,'').replace('___',q[2][0]):k==='tf'||k==='pick'?q[4]:q[2][0]};
const qWhy=q=>q[0]==='mc'?q[4]:q[3];
const gShuf=a=>{const b=a.map((t,j)=>j);for(let t=0;t<6;t++){for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}if(b.some((x,i)=>x!==i))break}return b};
function qHTML(q,id){const k=q[0];
 if(k==='mc'){const pin=j=>/possible|ikisi de|her ikisi/i.test(q[2][j]);const od=shuf(q[2].map((o,j)=>j).filter(j=>!pin(j))).concat(q[2].map((o,j)=>j).filter(pin));return `<p class="gq2">${esc(q[1])}</p><div class="opts">${od.map(j=>`<button class="opt" data-qo="${id}:${j}">${esc(q[2][j])}</button>`).join('')}</div>`}
 if(k==='gap'){const p=q[1].split('___');return `<p class="gq2">${esc(p[0])}<input class="ginl" id="${id}-in" autocomplete="off" autocapitalize="none" spellcheck="false">${esc(p[1]||'')}</p><button class="btn sm2" id="${id}-c">Kontrol et</button>`}
 if(k==='fix'){const l=gLbl(q[1]);return `<p class="gq2"><span class="gwq">${esc(gFixPre(q[1]))}</span>${l?` <small class="ex">(${esc(l)})</small>`:''}</p><input class="inp" id="${id}-in" value="${esc(gFixPre(q[1]))}" autocomplete="off" autocapitalize="none" spellcheck="false"><button class="btn sm2" id="${id}-c">Kontrol et</button>`}
 if(k==='tr')return `<p class="gq2">${esc(q[1])}</p><input class="inp" id="${id}-in" placeholder="İngilizcesini yaz" autocomplete="off" autocapitalize="none" spellcheck="false"><button class="btn sm2" id="${id}-c">Kontrol et</button>`;
 if(k==='ord'){const sh=gShuf(q[4]);return `<p class="gq2 sm">${esc(q[1])}</p><div class="orda" id="${id}-a"><span class="ex">${esc(q[6]||'Kelimelere sırayla dokun')}</span></div><div class="ordp" id="${id}-p">${sh.map(j=>`<button class="tile" data-ti="${j}">${esc(q[4][j])}</button>`).join('')}</div><div class="gbar" style="margin-top:8px"><button class="lnk" id="${id}-r">Sıfırla</button><button class="btn sm2" id="${id}-c" style="width:auto;margin:0">Kontrol et</button></div>`}
 if(k==='tf')return `<p class="gq2">${esc(q[1])}${q[5]?` <small class="ex">(${esc(q[5])})</small>`:''}</p><div class="opts two"><button class="opt" data-tf="${id}:1">✓ Doğru</button><button class="opt" data-tf="${id}:0">✗ Yanlış</button></div>`;
 if(k==='pick')return `<p class="gq2 pickw">${q[1].split(/\s+/).map((t,j)=>`<button class="pw" data-pw="${id}:${j}">${esc(t)}</button>`).join(' ')}</p>${q[5]?`<p class="ex">(${esc(q[5])})</p>`:''}`;
 return ''}
function qBind(q,id,done,alt){const k=q[0];
 if(k==='mc'){const bs=document.querySelectorAll(`[data-qo^="${id}:"]`);bs.forEach(b=>b.onclick=()=>{const j=+b.dataset.qo.split(':')[1];bs.forEach(x=>{x.disabled=true;if(+x.dataset.qo.split(':')[1]===q[3])x.classList.add('good')});if(j!==q[3])b.classList.add('bad');done(j===q[3]?'ok':'no')});return}
 if(k==='tf'){const bs=document.querySelectorAll(`[data-tf^="${id}:"]`);bs.forEach(b=>b.onclick=()=>{const v=b.dataset.tf.endsWith(':1');bs.forEach(x=>{x.disabled=true;if(x.dataset.tf.endsWith(q[2]?':1':':0'))x.classList.add('good')});if(v!==q[2])b.classList.add('bad');done(v===q[2]?'ok':'no')});return}
 if(k==='pick'){const bs=document.querySelectorAll(`[data-pw^="${id}:"]`);bs.forEach(b=>b.onclick=()=>{const j=+b.dataset.pw.split(':')[1];bs.forEach(x=>{x.disabled=true;if(+x.dataset.pw.split(':')[1]===q[2])x.classList.add('bad')});if(j!==q[2])b.classList.add('sel');done(j===q[2]?'ok':'no')});return}
 const c=$('#'+id+'-c');
 if(k==='ord'){const A=$('#'+id+'-a'),P=$('#'+id+'-p'),pick=[];const draw=()=>{A.innerHTML=pick.length?pick.map((j,i)=>`<button class="tile on" data-ta="${i}">${esc(q[4][j])}</button>`).join(''):`<span class="ex">${esc(q[6]||'Kelimelere sırayla dokun')}</span>`;
   P.querySelectorAll('.tile').forEach(t=>t.hidden=pick.includes(+t.dataset.ti));A.querySelectorAll('[data-ta]').forEach(t=>t.onclick=()=>{if(c.hidden)return;pick.splice(+t.dataset.ta,1);draw()})};
  P.querySelectorAll('.tile').forEach(t=>t.onclick=()=>{if(c.hidden)return;pick.push(+t.dataset.ti);draw()});$('#'+id+'-r').onclick=()=>{if(c.hidden)return;pick.length=0;draw()};
  c.onclick=()=>{if(pick.length<q[4].length){A.classList.add('shake');setTimeout(()=>A.classList.remove('shake'),400);return}const s=pick.map(j=>q[4][j]).join(' ')+q[5];const ok=q[2].some(a=>grN(a)===grN(s));c.hidden=true;$('#'+id+'-r').hidden=true;A.classList.add(ok?'good':'bad');done(ok?'ok':'no')};return}
 const inp=$('#'+id+'-in');const run=()=>{const r=grCheck(inp.value,[...q[2],...(alt||[])],k==='gap'?q[1]:null,k);if(!r)return;inp.disabled=true;c.hidden=true;done(r.v,inp.value)};c.onclick=run;inp.onkeydown=e=>{if(e.key==='Enter'&&!inp.disabled)run()}}
function qFb(q,v){const ok=v==='ok'||v==='near',r=qRight(q);let msg=ok?(v==='near'?'✓ Doğru sayıldı, küçük bir yazım hatası var':'✓ Doğru'):'✗ Yanlış';
 let body='';if(q[0]==='tf')body=q[2]?`<p>Bu cümle doğru. ${SP(r)}</p>`:`<p>Cümle hatalı. Doğrusu: <b>${esc(r)}</b> ${SP(r)}</p>`;
 else if(q[0]==='pick')body=`<p>Hatalı kelime: <b>${esc(q[1].split(/\s+/)[q[2]])}</b>. Doğrusu: <b>${esc(r)}</b> ${SP(r)}</p>`;
 else if(!(ok&&v==='ok'))body=`<p>Doğrusu: <b>${esc(r)}</b> ${SP(r)}</p>`;
 return `<div class="ckb ${ok?'good':'bad'}"><b>${msg}</b>${body}<p>${esc(qWhy(q))}</p></div>`}
// ---------- tekrar kuyruğu ----------
const GIV=[6e5,864e5,3*864e5,7*864e5,21*864e5];
const GQS=()=>S.grq||(S.grq={});
function gRec(uid,i,ok){const Q=GQS(),k=uid+'|'+i,e=Q[k];if(!ok){Q[k]={d:Date.now()+GIV[0],s:0}}else if(e){e.s++;if(e.s>=GIV.length)delete Q[k];else e.d=Date.now()+GIV[e.s]}save()}
const gDue=()=>Object.entries(GQS()).filter(([k,e])=>e.d<=Date.now()&&GU[k.split('|')[0]]);
const gTotQ=()=>Object.keys(GQS()).length;
function gNextDue(){const ds=Object.values(GQS()).map(e=>e.d).filter(d=>d>Date.now());if(!ds.length)return '';const m=Math.round((Math.min(...ds)-Date.now())/6e4);return m<60?`${m} dakika sonra`:m<1440?`${Math.round(m/60)} saat sonra`:`${Math.round(m/1440)} gün sonra`}
function gHomeCard(){const d=gDue().length;if(d)return `<button class="scard" onclick="gGoRev()"><span class="cv">✏️</span><span class="sx"><small>Dilbilgisi tekrarı</small><b>${d} soru seni bekliyor</b><small>Yanlış yaptığın sorular aralıklarla geri gelir</small></span></button>`;
 const G=GS(),l=S.grl||S.lvl||'A1',nx=GSYL[l].find(u=>GU[u[0]]&&!(G[u[0]]&&G[u[0]].best>=80));if(!nx)return '';return `<button class="scard" onclick="gGoUnit('${nx[0]}')"><span class="cv">📘</span><span class="sx"><small>Sıradaki dilbilgisi ünitesi (${l})</small><b>${esc(nx[1])}</b><small>${esc(nx[2])}</small></span></button>`}
function gGoRev(){GT='R';GTS=null;go('gunit')}
function gGoUnit(id){GT=null;GID=id;GTAB='k';GQ=null;GALL=false;go('gunit')}
// ---------- liste ----------
function gLvReady(l){return GSYL[l].every(u=>GU[u[0]])}
function gTestCard(){const r=gLvReady(GL),t=(S.grt||{})[GL];
 return `<div class="card left" style="margin-bottom:10px"><p class="big sm" style="margin:0">${GL} seviye testi</p><p class="ex" style="margin:4px 0 8px">${r?`Bütün ${GL} konularından karışık 40 soru. %70 ve üstü seviyeyi geçtiğini gösterir; sonunda zayıf olduğun üniteler listelenir.${t?` En iyi sonucun %${t.best}${t.best>=70?', geçtin ✓':''}.`:''}`:`Bu seviyenin bütün üniteleri hazır olunca açılacak.`}</p>${r?`<button class="btn" id="gtst">${t?'Testi tekrar çöz':'Teste başla'}</button>`:''}</div>`}
function gRevCard(){const d=gDue().length,tot=gTotQ(),done=Object.keys(GS()).filter(id=>GU[id]).length;if(!tot&&!done)return '';
 return `<div class="card left" style="margin-bottom:10px"><p class="big sm" style="margin:0">Tekrar ve karışık pratik</p><p class="ex" style="margin:4px 0 8px">${tot?`Tekrar listende ${tot} soru var${d?`, ${d} tanesi şimdi hazır`:`; sıradaki ${gNextDue()}`}. Yanlış yaptığın sorular 10 dakika, 1, 3, 7 ve 21 gün sonra tekrar gelir; doğru bildikçe aralık uzar.`:'Yanlış yaptığın sorular burada birikir ve aralıklarla tekrar sorulur.'}</p>
 <div class="gbar" style="gap:8px">${d?`<button class="btn" id="grev" style="margin:0">Tekrar et (${d})</button>`:''}${done?`<button class="btn no" id="gmix" style="margin:0">Karışık pratik</button>`:''}</div></div>`}
// ---------- konu araması ----------
const gNorm=s=>String(s).toLocaleLowerCase('tr').replace(/[çğıöşüâîû]/g,c=>({ç:'c',ğ:'g',ı:'i',ö:'o',ş:'s',ü:'u',â:'a',î:'i',û:'u'}[c])).replace(/[’`]/g,"'");
let GIX=null,GSQ='';
function gIndex(){if(GIX)return GIX;GIX=[];for(const l of GLV)GSYL[l].forEach((u,i)=>{const U=GU[u[0]];if(!U)return;const H=[],B=[];
 U.b.forEach(b=>{const k=b[0],v=b[1];if(k==='h'&&v!=='Konuyu metinde gör')H.push(v);else if(k==='p'||k==='tip')B.push(v);else if(k==='tb')v.forEach(r=>B.push(r.filter(Boolean).join(' · ')));else if(k==='eg')v.forEach(([e,t])=>B.push(e+' – '+t));else if(k==='err')v.forEach(([w,r,n])=>B.push(r+' – '+n))});
 GIX.push({id:u[0],l,n:i+1,t:u[1],tt:u[2],T:gNorm(u[1]+' '+u[2]),H:H.map(h=>[h,gNorm(h)]),B:B.map(x=>[x,gNorm(x)])})});return GIX}
function gSnip(x,ws){const n=gNorm(x);let p=-1;for(const w of ws){p=n.indexOf(w);if(p>=0)break}if(p<0)return esc(x.slice(0,110));const a=Math.max(0,p-45),b=Math.min(x.length,p+75);let out=esc(x.slice(a,b));
 ws.forEach(w=>{const re=new RegExp('('+w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','gi');out=out.replace(re,'\u0001$1\u0002')});out=out.replace(/\u0001/g,'<mark>').replace(/\u0002/g,'</mark>');return (a?'…':'')+out+(b<x.length?'…':'')}
function gSearch(q){const ph=gNorm(q).trim().replace(/\s+/g,' '),ws=ph.split(' ').filter(w=>w.length>=2);if(!ws.length)return null;let res=[];
 for(const e of gIndex()){const all=e.T+' '+e.H.map(h=>h[1]).join(' ')+' '+e.B.map(b=>b[1]).join(' ');if(!ws.every(w=>all.includes(w)))continue;
  let sc=0;ws.forEach(w=>{if(e.T.includes(w))sc+=12;if(e.H.some(h=>h[1].includes(w)))sc+=5;sc+=Math.min(4,e.B.filter(b=>b[1].includes(w)).length)});
  const inT=ws.every(w=>e.T.includes(w)),hit=inT?null:(e.H.find(h=>ws.some(w=>h[1].includes(w)))||e.B.find(b=>ws.some(w=>b[1].includes(w))));
  const exact=ph.includes(' ')&&all.includes(ph);if(exact)sc+=30;
  res.push([sc,e,hit?gSnip(hit[0],exact?[ph]:ws):'',exact])}
 if(ph.includes(' ')&&res.some(r=>r[3]))res=res.filter(r=>r[3]);
 return res.sort((a,b)=>b[0]-a[0]||GLV.indexOf(a[1].l)-GLV.indexOf(b[1].l)).slice(0,40)}
function gSearchView(){const box=$('#gres');if(!box)return;const r=gSearch(GSQ);const lv=$('#glv');
 if(!r){box.innerHTML='';if(lv)lv.hidden=false;return}if(lv)lv.hidden=true;const G=GS();
 box.innerHTML=`<p class="gh">“${esc(GSQ)}” için ${r.length?r.length+' ünite':'sonuç yok'}</p>`+(r.length?r.map(([sc,e,sn])=>{const g=G[e.id];return `<button class="brow gu" data-gu="${e.id}"><span><small class="gsl">${e.l} · Ünite ${e.n}</small><b>${esc(e.t)}</b><small>${esc(e.tt)}</small>${sn?`<small class="gsn">${sn}</small>`:''}</span><span class="bst">${g?'%'+g.best:''}</span></button>`}).join(''):'<p class="ex">Başka bir kelime dene: Türkçe (keşke, edilgen, sıfat) ya da İngilizce (whom, used to, unless).</p>');
 box.querySelectorAll('[data-gu]').forEach(b=>b.onclick=()=>gGoUnit(b.dataset.gu))}
function grammar(){$('#cnt').textContent='';const G=GS();if(!GL)GL=S.grl||'A1';
 const ready=Object.keys(GU).length,total=GLV.reduce((a,l)=>a+GSYL[l].length,0);
 $('#main').innerHTML=`<div class="card left"><p class="big sm">Dilbilgisi</p><p class="se">A1'den C2'ye ${total} ünite. Her ünite bir ders gibi ilerler: konu bölüm bölüm anlatılır, aralarda farklı türde sorular gelir, sonunda ayrı alıştırma seti vardır.</p><p class="ex">${ready===total?'Bütün üniteler hazır. Her seviyenin başında o seviyenin karışık testi var.':ready+' ünite hazır, diğerleri sırayla ekleniyor.'}</p></div>${gRevCard()}<div class="gsrch"><input class="inp" id="gq" type="search" placeholder="Konu ara: keşke, edilgen, whom, used to…" autocomplete="off" autocapitalize="none" spellcheck="false" value="${esc(GSQ)}"></div><div id="gres"></div><div id="glv"><div class="seg">${GLV.map(l=>`<button data-gl="${l}" class="${GL===l?'on':''}">${l}</button>`).join('')}</div>
 <p class="gh">${GL}: ${GLN[GL]}</p>${gTestCard()}${GSYL[GL].map((u,i)=>{const r=GU[u[0]],g=G[u[0]];return `<button class="brow gu" data-gu="${u[0]}" ${r?'':'disabled'}><span><small>Ünite ${i+1}${r?'':', yakında'}</small><b>${esc(u[1])}</b><small>${esc(u[2])}</small></span><span class="bst">${g?'%'+g.best:''}</span></button>`}).join('')}</div>`;
 const qi=$('#gq');let gqt=null;qi.oninput=()=>{clearTimeout(gqt);gqt=setTimeout(()=>{GSQ=qi.value.trim();gSearchView()},150)};if(GSQ)gSearchView();
 document.querySelectorAll('[data-gl]').forEach(b=>b.onclick=()=>{GL=b.dataset.gl;S.grl=GL;save();grammar()});
 const tb=$('#gtst');if(tb)tb.onclick=()=>{GT=GL;GTS=null;go('gunit')};
 const rv=$('#grev');if(rv)rv.onclick=gGoRev;const mx=$('#gmix');if(mx)mx.onclick=()=>{GT='M';GTS=null;go('gunit')};
 document.querySelectorAll('[data-gu]').forEach(b=>b.onclick=()=>gGoUnit(b.dataset.gu))}
// ---------- ders ----------
function gSecs(bs){const out=[];bs.forEach(b=>{if(b[0]==='h'||!out.length)out.push([]);out[out.length-1].push(b)});return out}
function gBlocks(bs,pre){return bs.map(([k,v],bi)=>k==='ask'?`<div class="gask"><p class="gal">✏️ Kendini dene: ${QL[v[0]].charAt(0).toLowerCase()+QL[v[0]].slice(1)}</p>${qHTML(v,pre+'-'+bi)}<div id="${pre}-${bi}-fb"></div></div>`:k==='h'?`<p class="gh2">${esc(v)}</p>`:k==='p'?`<p class="gp">${esc(v)}</p>`:
 k==='tb'?`<div class="gtw"><table class="gtb">${v.map((r,i)=>`<tr>${r.map(c=>i?`<td>${esc(c)}</td>`:`<th>${esc(c)}</th>`).join('')}</tr>`).join('')}</table></div>`:
 k==='eg'?`<div class="geg">${v.map(([en,tr])=>`<div><p class="gen">${esc(en)} ${SP(en)}</p><p class="ex">${esc(tr)}</p></div>`).join('')}</div>`:
 k==='tip'?`<div class="gtip"><b class="gtb">${MVSVG('n',26)}Mavi'nin notu: Türkçeden farkı</b><p>${esc(v)}</p></div>`:
 k==='err'?`<div class="gerr"><b>Sık yapılan hatalar</b>${v.map(([w,r,n])=>`<p><span class="gw">✗ ${esc(w)}</span><br><span class="gr">✓ ${esc(r)}</span><br><small>${esc(n)}</small></p>`).join('')}</div>`:
 k==='ctx'?gCtxHTML(v,pre+'-'+bi):'').join('')}
function gBindBlocks(bs,pre){bs.forEach(([k,v],bi)=>{const id=pre+'-'+bi;if(k==='ask')qBind(v,id,(r)=>{const fb=$('#'+id+'-fb');if(fb)fb.innerHTML=qFb(v,r)});if(k==='ctx')gCtxBind(v,id)})}
// Bağlamda: ('ctx',{t:başlık,x:'metin ___ (1) ...',a:[[cevaplar],...],n:[açıklamalar]})
function gCtxHTML(v,id){let i=0;const html=esc(v.x).replace(/___/g,()=>{const j=i++;return `<input class="ginl" id="${id}-g${j}" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="${j+1}">`});
 return `<div class="gctx"><p class="gal">📖 Bağlamda: ${esc(v.t)}</p><p class="gctxx">${html.replace(/\n/g,'<br>')}</p>${v.tr?`<details><summary class="ex">Türkçesi</summary><p class="ex">${esc(v.tr)}</p></details>`:''}<button class="btn sm2" id="${id}-c">Kontrol et</button><div id="${id}-fb"></div></div>`}
function gCtxBind(v,id){const c=$('#'+id+'-c');if(!c)return;c.onclick=()=>{let ok=0;const rows=v.a.map((ans,j)=>{const inp=$('#'+id+'-g'+j),r=grCheck(inp.value,ans,null,'gap'),good=r&&r.v==='ok';if(good)ok++;inp.classList.add(good?'okk':'nok');inp.disabled=true;return `<p>${j+1}. ${good?'✓':'✗'} <b>${esc(ans[0])}</b>${v.n&&v.n[j]?`: ${esc(v.n[j])}`:''}</p>`});
 c.hidden=true;$('#'+id+'-fb').innerHTML=`<div class="ckb ${ok===v.a.length?'good':ok>=v.a.length/2?'part':'bad'}"><b>${ok} / ${v.a.length} doğru</b>${rows.join('')}</div>`;const full=v.x.replace(/___/g,()=>'');}}
function gunit(){if(GT)return gSess();const u=GU[GID],inf=gUnitInfo(GID);if(!u||!inf)return go('grammar');const G=GS(),g=G[GID],idx=GSYL[inf.l].findIndex(x=>x[0]===GID),A=gAll(GID);
 $('#cnt').textContent=`Dilbilgisi ${inf.l}: ünite ${idx+1} / ${GSYL[inf.l].length}`;
 const head=`<button class="lnk" id="gback" style="margin:-4px 0 6px">‹ Üniteler</button><p class="ex" style="margin:0">${inf.l}, ünite ${idx+1}</p><p class="big sm" style="margin:0">${esc(inf.t)}</p><p class="ex" style="margin:0 0 10px">${esc(inf.tt)}${g?`, en iyi sonucun %${g.best}`:''}</p><div class="seg"><button data-gt="k" class="${GTAB==='k'?'on':''}">Konu anlatımı</button><button data-gt="a" class="${GTAB==='a'?'on':''}">Alıştırmalar (${A.all.length})</button></div>`;
 if(GTAB==='k'){const secs=gLesson(GID),SP_=S.grs||(S.grs={});let ptr=GALL?secs.length-1:Math.min(SP_[GID]||0,secs.length-1);
  $('#main').innerHTML=head+`<div class="gbar"><span class="ex">Bölüm ${ptr+1} / ${secs.length}</span><button class="lnk" id="gall">${GALL?'Bölüm bölüm ilerle':'Tamamını göster'}</button></div>`+
  secs.slice(0,ptr+1).map((sb,si)=>`<div class="card left gcard" id="gs${si}">${gBlocks(sb,'a'+si)}</div>`).join('')+
  (ptr<secs.length-1?`<button class="btn" id="gnext">Devam et ›</button>`:`<div class="card left"><p class="big sm">Konu bitti 🎉</p><p class="se">Şimdi ${A.all.length} soruluk alıştırma setiyle pekiştir. Sette yedi farklı soru türü var: seçme, boşluk doldurma, hata düzeltme, çeviri, kelime dizme, doğru mu yanlış mı ve hatalı kelimeyi bulma.</p><button class="btn" id="gstart">Alıştırmalara geç</button><button class="btn no" id="gtop" style="margin-top:8px">Konuyu baştan oku</button></div>`);
  secs.slice(0,ptr+1).forEach((sb,si)=>gBindBlocks(sb,'a'+si));
  const gn=$('#gnext');if(gn)gn.onclick=()=>{SP_[GID]=ptr+1;save();gunit();const el=$('#gs'+(ptr+1));if(el)try{el.scrollIntoView({behavior:'smooth',block:'start'})}catch(e){}};
  const gs=$('#gstart');if(gs)gs.onclick=()=>{GTAB='a';GQ=null;gunit();try{window.scrollTo(0,0)}catch(e){}};
  const gt=$('#gtop');if(gt)gt.onclick=()=>{SP_[GID]=0;GALL=false;save();gunit();try{window.scrollTo(0,0)}catch(e){}};
  $('#gall').onclick=()=>{GALL=!GALL;gunit()}}
 else{if(!GQ)GQ={src:'u',items:A.order.map(i=>[GID,i]),i:0,ok:0,wrong:[],res:null};gPlay(head)}
 $('#gback').onclick=()=>go('grammar');document.querySelectorAll('[data-gt]').forEach(b=>b.onclick=()=>{GTAB=b.dataset.gt;if(GTAB==='a')GQ=null;gunit()})}
// ---------- oturum (ünite seti, seviye testi, tekrar, karışık) ----------
const gQ=([u,i])=>gAll(u).all[i];
function gPlay(head){const T=GQ,n=T.items.length;if(T.i>=n)return gFinish(head);
 const [uid,qi]=T.items[T.i],q=gQ(T.items[T.i]),k=q[0],inf=gUnitInfo(uid),alt=(S.gralt||{})[uid+':'+qi]||[];
 $('#main').innerHTML=head+`<div class="tk" style="margin-bottom:10px"><i style="width:${T.i/n*100}%"></i></div><p class="ex">Soru ${T.i+1} / ${n}: ${QL[k]}${T.src!=='u'?` · <span class="gtag">${esc(inf.l)} · ${esc(inf.tt)}</span>`:''}</p><div class="card left gplay">${qHTML(q,'gp')}</div><div id="gfb"></div>`;
 const bk=$('#gback');if(bk)bk.onclick=()=>{GT=null;go('grammar')};
 qBind(q,'gp',(v,val)=>{const okk=v==='ok'||v==='near';if(T.res===null){T.res=okk;if(okk)T.ok++;else T.wrong.push(T.items[T.i]);gRec(uid,qi,okk)}
  let extra='';if(v==='no'&&k==='tr')extra=`<button class="lnk" id="gai" hidden>Kontrol et</button><div id="gaim"></div>`;
  $('#gfb').innerHTML=qFb(q,v)+extra+`<button class="btn" id="gnx" style="margin-top:10px">${T.i+1<n?'Sonraki soru':'Sonucu gör'}</button>`+rpLink({s:'g',id:uid+':'+qi,l:'Dilbilgisi '+uid+' · '+QL[k],q:q[1]});
  $('#gnx').onclick=()=>{T.i++;T.res=null;gPlay(head);try{window.scrollTo(0,0)}catch(e){}};if(okk)say(qRight(q));
  const ga=$('#gai');if(ga)ga.onclick=async()=>{ga.disabled=true;ga.textContent='Kontrol ediliyor...';
   try{const res=await ai('A Turkish learner translated a Turkish sentence into English. Decide if the translation is grammatically correct AND has the same meaning (accept natural alternatives). Return ONLY JSON: {"v":"correct"|"wrong","fixed":"<a corrected version of the learner sentence, or empty if correct>","why":"<one short sentence in Turkish>"}\nTurkish: '+q[1]+'\nModel answers: '+q[2].join(' | ')+'\nLearner: '+val,true);
    const ok=String(res&&res.v).toLowerCase()==='correct';
    if(ok){const key=uid+':'+qi;S.gralt=S.gralt||{};(S.gralt[key]=S.gralt[key]||[]).push(String(val).trim());const w=T.wrong.findIndex(x=>x[0]===uid&&x[1]===qi);if(w>=0){T.wrong.splice(w,1);T.ok++}gRec(uid,qi,true);save()}
    $('#gaim').innerHTML=`<p class="${ok?'vd good':''}">${ok?'Claude: cevabın doğru. Bundan sonra kabul edilecek.':'Claude: '+esc(res&&res.why||'cevap doğru değil.')}</p>${!ok&&res&&res.fixed?`<p>Düzeltilmiş hâli: <b>${esc(res.fixed)}</b></p>`:''}`;ga.remove()}
   catch(e){$('#gaim').innerHTML=`<p class="ex">${aiErr(e)}</p>`;ga.remove()}}},alt)}
function gFinish(head){const T=GQ,n=T.items.length,pct=Math.round(T.ok/n*100);
 if(T.src==='u'){const u=GU[GID],G=GS(),full=n===gAll(GID).all.length,inf=gUnitInfo(GID);
  if(full){const g=G[GID]||{best:0};g.best=Math.max(g.best||0,pct);g.last=pct;g.at=Date.now();G[GID]=g;if(pct>=60){const Y=YOLS(),k='et:'+GID,st=pct===100?3:pct>=80?2:1;if(!(Y[k]>=st))Y[k]=st}save();gmDone('gr',pct)}
  const nx=(()=>{const L=GSYL[inf.l],i=L.findIndex(x=>x[0]===GID);for(let j=i+1;j<L.length;j++)if(GU[L[j][0]])return L[j][0];return null})();
  const byT={};T.items.forEach(it=>{const k=gQ(it)[0];byT[k]=byT[k]||[0,0];byT[k][1]++});T.wrong.forEach(it=>{byT[gQ(it)[0]][0]++});
  const weakT=Object.entries(byT).filter(([k,[w,t]])=>w&&w/t>=.5).map(([k])=>QL[k].toLowerCase());
  $('#main').innerHTML=head+`<div class="card left"><p class="big sm">${pct>=90?'Harika! 🎉':pct>=70?'İyi iş!':'Biraz daha pratik'}</p><p class="se">${T.ok} / ${n} doğru (%${pct}).</p><p class="ex">${pct>=80?'Bu üniteyi büyük ölçüde öğrendin.':'Konu anlatımına tekrar bakıp yanlışlarını yeniden çözmeni öneririm.'}${weakT.length?` Zorlandığın soru türü: ${weakT.join(', ')}.`:''}${T.wrong.length?' Yanlışların tekrar listene eklendi; 10 dakika sonra ve sonraki günlerde yeniden sorulacak.':''}</p>
  ${T.wrong.length?`<button class="btn" id="gwr">Yanlışları şimdi tekrar çöz (${T.wrong.length})</button>`:''}<button class="btn no" id="gre" style="margin-top:8px">Üniteyi baştan çöz</button>${nx?`<button class="btn no" id="gnu" style="margin-top:8px">Sonraki ünite: ${esc(gUnitInfo(nx).t)}</button>`:''}<button class="btn no" id="gkon" style="margin-top:8px">Konu anlatımına dön</button></div>`;
  const w=$('#gwr');if(w)w.onclick=()=>{GQ={src:'u',items:[...T.wrong],i:0,ok:0,wrong:[],res:null,part:1};gunit()};
  $('#gre').onclick=()=>{GQ=null;gunit()};$('#gkon').onclick=()=>{GTAB='k';gunit()};const nu=$('#gnu');if(nu)nu.onclick=()=>gGoUnit(nx);
  $('#gback').onclick=()=>go('grammar');document.querySelectorAll('[data-gt]').forEach(b=>b.onclick=()=>{GTAB=b.dataset.gt;if(GTAB==='a')GQ=null;gunit()});return}
 const byU={},tot={};T.items.forEach(([id])=>tot[id]=(tot[id]||0)+1);T.wrong.forEach(([id])=>byU[id]=(byU[id]||0)+1);
 const weak=Object.keys(byU).sort((a,b)=>byU[b]/tot[b]-byU[a]/tot[a]);
 let top='';
 if(T.src==='t'){S.grt=S.grt||{};const t=S.grt[T.l]||{best:0};t.best=Math.max(t.best||0,pct);t.last=pct;t.at=Date.now();S.grt[T.l]=t;save();gmDone('grt',pct);const pass=pct>=70,nl=GLV[GLV.indexOf(T.l)+1];
  top=`<p class="big sm">${pass?'Seviyeyi geçtin! 🎉':'Biraz daha çalışmak gerek'}</p><p class="se">${T.ok} / ${n} doğru (%${pct}).</p><p class="ex">${pass?(nl?`${T.l} konularına hâkimsin, ${nl} seviyesine geçebilirsin.`:'Bu seviyeye hâkimsin.'):`Geçmek için %70 gerekiyor. Aşağıdaki ünitelere tekrar bakmanı öneririm.`}</p>${pass&&nl?`<button class="btn no" id="gtn" style="margin-top:8px">${nl} ünitelerine geç</button>`:''}`}
 else top=`<p class="big sm">${pct>=80?'Çok iyi! 🎉':'Tekrar bitti'}</p><p class="se">${T.ok} / ${n} doğru (%${pct}).</p><p class="ex">${T.src==='R'?`Doğru bildiklerin daha uzun aralıkla, yanlışların 10 dakika sonra yeniden gelecek. Tekrar listende ${gTotQ()} soru var.`:'Karışık pratik farklı ünitelerin sorularını bir araya getirir; bu, konuları birbirinden ayırt etmeyi güçlendirir.'}</p>`;
 $('#main').innerHTML=head+`<div class="card left">${top}</div>${weak.length?`<p class="gh">Tekrar bakman gereken üniteler</p>${weak.map(id=>{const inf=gUnitInfo(id);return `<button class="brow gu" data-gw="${id}"><span><small>${inf.l}</small><b>${esc(inf.t)}</b><small>${esc(inf.tt)}</small></span><span class="bst">${byU[id]} / ${tot[id]} yanlış</span></button>`}).join('')}`:''}
 <button class="btn" id="gtr" style="margin-top:10px">${T.src==='t'?'Testi yeniden çöz (yeni sorular)':T.src==='R'?(gDue().length?`Tekrara devam et (${gDue().length})`:'Dilbilgisine dön'):'Yeni karışık set'}</button>`;
 $('#gback').onclick=()=>{GT=null;go('grammar')};
 $('#gtr').onclick=()=>{if(T.src==='R'&&!gDue().length){GT=null;return go('grammar')}GTS=null;gSess();try{window.scrollTo(0,0)}catch(e){}};
 const gn=$('#gtn');if(gn)gn.onclick=()=>{const nl=GLV[GLV.indexOf(T.l)+1];GT=null;GL=nl;S.grl=nl;save();go('grammar')};
 document.querySelectorAll('[data-gw]').forEach(b=>b.onclick=()=>gGoUnit(b.dataset.gw))}
const gRnd=a=>{for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
function gSess(){let title,src;
 if(GT==='R'){title='Dilbilgisi tekrarı';src='R'}else if(GT==='M'){title='Karışık pratik';src='M'}else{title=GT+' seviye testi';src='t'}
 if(!GTS){let items=[];
  if(src==='R')items=gRnd(gDue().map(([k])=>{const [u,i]=k.split('|');return [u,+i]}).filter(([u,i])=>gAll(u).all[i])).slice(0,20);
  else if(src==='M'){const G=GS(),ids=Object.keys(G).filter(id=>GU[id]).sort((a,b)=>(G[a].best||0)-(G[b].best||0));const pool=ids.slice(0,12);
   pool.forEach((id,pi)=>{const A=gAll(id),idx=gRnd(A.all.map((_,i)=>i).filter(i=>A.all[i][0]!=='tr'));items.push(...idx.slice(0,pi<4?3:1).map(i=>[id,i]))});items=gRnd(items).slice(0,15)}
  else{const units=GSYL[GT].map(u=>u[0]),N=40,pool=units.map(id=>gRnd(gAll(id).all.map((q,i)=>[id,i]).filter(([u,i])=>gAll(u).all[i][0]!=='tr')));let r=0;
   while(items.length<N&&pool.some(p=>p.length>r)){pool.forEach(p=>{if(items.length<N&&p[r])items.push(p[r])});r++}items=gRnd(items)}
  GTS={src,l:GT,items};GQ={src,l:GT,items,i:0,ok:0,wrong:[],res:null}}
 $('#cnt').textContent=title;
 const head=`<button class="lnk" id="gback" style="margin:-4px 0 6px">‹ Dilbilgisi</button><p class="big sm" style="margin:0 0 10px">${esc(title)}</p>`;
 if(!GQ.items.length){$('#main').innerHTML=head+`<div class="card left"><p class="se">Şu an soru yok.</p></div>`;$('#gback').onclick=()=>{GT=null;go('grammar')};return}
 gPlay(head)}

