 const B=BS(),oa=OA.secs.filter(s=>LVOA[L].includes(s.lvl)),st=STORIES.filter(s=>s.l===L),is=IDS.filter(s=>s[0]===L);S.rd=S.rd||{};const R2=S.idsr||{};
 const od=oa.filter(s=>B.done[skey('oa',s)]!=null).length,sd=st.filter(s=>S.rd[s.id]!=null).length,isd=is.filter(s=>R2[s[1]]!==undefined).length;
 const no=oa.find(s=>B.done[skey('oa',s)]==null),ns=st.find(s=>S.rd[s.id]==null),nis=is.findIndex(s=>R2[s[1]]===undefined);
 const rn=oa.length+st.length+is.length;
