// ----- seviye tespit sınavı -----
let PL=null;
function plQ(L,used){const out=[],G=[];for(const u of GSYL[L]){const U=GU[u[0]];if(!U)continue;U.q.forEach((q,j)=>{if(q[0]==='mc'&&q[2].length>=3&&!/\(/.test(q[1])&&!used.has(u[0]+'|'+j))G.push([u[0],j,q])})}
 const byU={};shuf(G).forEach(g=>{if(!byU[g[0]])byU[g[0]]=g});const gs=shuf(Object.values(byU)).slice(0,4);gs.forEach(g=>{used.add(g[0]+'|'+g[1]);const o=shuf(g[2][2].map((x,i)=>i));out.push(['mc',g[2][1],o.map(i=>g[2][2][i]),o.indexOf(g[2][3]),g[2][4]])});
 const vw=shuf(words.filter(w=>w.l===L&&!used.has('w|'+w.w))),vi=shuf(IDD.map((r,i)=>i).filter(i=>IDD[i][1]===L&&IDD[i][2]==='d'&&!used.has('i|'+i)));
 const wq=w=>{used.add('w|'+w.w);const ds=shuf(words.filter(x=>x.tr!==w.tr&&x.p===w.p)).slice(0,3).map(x=>x.tr),o=shuf([w.tr,...ds]);return ['mc',`“${w.w}” (${w.p}) ne demek?`,o,o.indexOf(w.tr),`${w.w}: ${w.tr}`]};
 const iq=i=>{used.add('i|'+i);const q=iMC(i,`“${IDD[i][0]}” ne anlama gelir?`,5);return q};
 const need=6-out.length;for(let k=0;k<need;k++){if(k%2===0&&vw.length)out.push(wq(vw.shift()));else if(vi.length)out.push(iq(vi.shift()));else if(vw.length)out.push(wq(vw.shift()))}
 return shuf(out)}
function plStart(){PL={st:'intro'};go('plc')}
function plc(){$('#cnt').textContent='';const M=$('#main');if(!PL){go('seviye');return}
 if(PL.st==='intro'){M.innerHTML=`<div class="gbar"><button class="lnk" id="pback">‹ Vazgeç</button></div><div class="card left"><p class="big sm" style="margin:0">Seviye tespit sınavı</p><p class="se" style="margin:8px 0">Dilbilgisi ve kelime bilgini ölçen, uyarlanabilir bir sınav. Her turda 6 soru gelir; iyi yaparsan bir üst seviyeye, zorlanırsan bir alt seviyeye geçersin. Genellikle 3-5 tur, yani 10-15 dakika sürer.</p><p class="ex">Bilmediğin soruda tahmin yapma; sonucun daha doğru olur. Sınav tekrar listene ya da puanlarına eklenmez.</p>
  <p class="gal" style="margin-top:12px">İngilizcen hakkında ne düşünüyorsun?</p><div class="opts">${[['A1','Yeni başlıyorum'],['A2','Temel şeyleri anlıyorum'],['B1','Günlük konuşmaları idare ediyorum'],['B2','Rahatça okuyup konuşabiliyorum']].map(([l,t])=>`<button class="opt" data-ps="${l}">${t}</button>`).join('')}</div></div>`;
  $('#pback').onclick=()=>{PL=null;go(S.lvl?'seviye':'home')};
  document.querySelectorAll('[data-ps]').forEach(b=>b.onclick=()=>{PL={st:'q',cur:b.dataset.ps,res:{},used:new Set(),blk:0};PL.qs=plQ(PL.cur,PL.used);PL.k=0;PL.ok=0;plc()});return}
 if(PL.st==='done'){const r=PL.result;if(!PL.gmd){PL.gmd=1;gmDone('plc')}M.innerHTML=`<div class="card"><p class="ex" style="margin:0">Önerilen seviyen</p><p class="big" style="font-size:54px;margin:4px 0">${r}</p><p class="se">${LVN[r]}</p>
  <div class="lvres">${LVL.filter(l=>PL.res[l]!==undefined).map(l=>`<div><b>${l}</b><span>${PL.res[l]} / 6</span><i class="${PL.res[l]>=5?'ok':PL.res[l]<=3?'no':'mid'}"></i></div>`).join('')}</div>
  <p class="ex" style="text-align:left">${plWhy(r)}</p><button class="btn" id="papply">${r} seviyesiyle başla</button><button class="btn no" id="pkarne" style="margin-top:8px">🎓 Karneni gör ve paylaş</button><button class="btn no" id="pother" style="margin-top:8px">Başka bir seviye seçeceğim</button></div>`;
  $('#pkarne').onclick=()=>{lvSet(r);LVV=null;S.plc={l:r,d:Date.now(),res:PL.res};S.plcSkip=true;save();PL=null;go('karne')};
  $('#papply').onclick=()=>{lvSet(r);LVV=null;S.plc={l:r,d:Date.now(),res:PL.res};S.plcSkip=true;save();PL=null;go('seviye')};
  $('#pother').onclick=()=>{LVV=r;S.plc={l:r,d:Date.now(),res:PL.res};S.plcSkip=true;save();PL=null;go('seviye')};return}
 const q=PL.qs[PL.k],id='pq'+PL.blk+'_'+PL.k,tot=PL.qs.length;
 M.innerHTML=`<div class="gbar"><button class="lnk" id="pback">‹ Sınavı bırak</button><span class="ex">Tur ${PL.blk+1} · Soru ${PL.k+1} / ${tot}</span></div><div class="tk" style="margin-bottom:10px"><i style="width:${PL.k/tot*100}%"></i></div>
 <div class="card left gplay"><p class="gal">${QL[q[0]]}</p>${qHTML(q,id)}<button class="lnk" id="pskip" style="margin-top:10px">Bilmiyorum, geç</button></div>`;
 $('#pback').onclick=()=>{PL=null;go(S.lvl?'seviye':'home')};
 const nxt=ok=>{if(ok)PL.ok++;PL.k++;if(PL.k<tot){plc();return}plBlockEnd()};
 qBind(q,id,v=>{setTimeout(()=>nxt(v==='ok'),350)});$('#pskip').onclick=()=>nxt(false)}
function plBlockEnd(){const L=PL.cur,s=PL.ok,i=LVL.indexOf(L);PL.res[L]=s;PL.blk++;let fin=null;
 if(s>=5){if(i===LVL.length-1)fin=L;else if(PL.res[LVL[i+1]]!==undefined)fin=LVL[i+1];else PL.cur=LVL[i+1]}
 else if(s<=3){if(i===0)fin=L;else if(PL.res[LVL[i-1]]!==undefined)fin=L;else PL.cur=LVL[i-1]}
 else fin=L;
 if(!fin&&PL.blk>=6)fin=PL.cur;
 if(fin){PL.st='done';PL.result=fin;plc();return}
 PL.qs=plQ(PL.cur,PL.used);PL.k=0;PL.ok=0;plc()}
function plWhy(r){const R=PL.res,i=LVL.indexOf(r),lower=LVL.slice(0,i).filter(l=>R[l]>=5),here=R[r];
 if(r==='C2'&&here>=5)return 'C2 sorularının neredeyse hepsini doğru cevapladın. Ustalık seviyesindesin; C2 planındaki ileri konular ve metinlerle çalışmaya devam edebilirsin.';
 if(here===undefined)return `${lower.length?lower.join(', ')+' sorularında başarılıydın. ':''}Bir sonraki adım ${r}.`;
 return `${lower.length?lower[lower.length-1]+' seviyesindeki soruların çoğunu doğru cevapladın. ':''}${r} sorularında ${here} / 6 doğru yaptın; bu seviyenin konularını çalışmak sana en çok faydayı sağlar. Bu sınav dilbilgisi ve kelime bilgisini ölçer; okuma ve dinleme becerin farklı olabilir. İstediğin zaman seviyeni değiştirebilirsin.`}

const YOLEP=[{"id":"A1-1","l":"A1","n":1,"t":"A New Town","p":[["Deniz is nineteen. She is from Izmir, in Turkey. Today she is on a bus in England. She is tired, but she is happy.","Deniz on dokuz yaşında. Türkiye'de, İzmir'den. Bugün İngiltere'de bir otobüste. Yorgun ama mutlu."],["The bus stops in a small town by the sea. The town is Port Wren. There are white houses, small boats and a lot of birds.","Otobüs denize yakın küçük bir kasabada duruyor. Kasabanın adı Port Wren. Beyaz evler, küçük tekneler ve bir sürü kuş var."],["A woman is at the bus stop. \"Hello! Are you Deniz? I'm Mrs Penrose.\" Deniz has a room in her house, above a bakery.","Otobüs durağında bir kadın var. \"Merhaba! Sen Deniz misin? Ben Bayan Penrose.\" Deniz'in onun evinde, bir fırının üstünde bir odası var."],["From her window, Deniz can see an old lighthouse. It is tall and white, but there is no light. \"Why is it dark?\" she asks. Mrs Penrose doesn't answer.","Deniz penceresinden eski bir deniz feneri görebiliyor. Uzun ve beyaz ama ışığı yok. \"Neden karanlık?\" diye soruyor. Bayan Penrose cevap vermiyor."]],"q":[["Where is Deniz from?",["Istanbul","Izmir","Port Wren"],1,"'She is from Izmir, in Turkey.'"],["Where is Deniz's room?",["above a bakery","next to the sea","in a hotel"],0,"'above a bakery'"],["What is strange about the lighthouse?",["it is very small","there is no light","it is red"],1,"'there is no light'"]],"w":103},{"id":"A1-2","l":"A1","n":2,"t":"Breakfast at the Bakery","p":[["In the morning, the house smells of bread. Deniz goes down to the bakery. Mrs Penrose is busy. Her grandson Tom is there too.","Sabah ev ekmek kokuyor. Deniz aşağıya, fırına iniyor. Bayan Penrose meşgul. Torunu Tom da orada."],["Tom is twelve. He has red hair and a big smile. \"Do you like tea?\" he asks. \"Yes, I love tea,\" says Deniz. \"In Turkey we drink a lot of tea.\"","Tom on iki yaşında. Kızıl saçları ve kocaman bir gülümsemesi var. \"Çay sever misin?\" diye soruyor. \"Evet, çaya bayılırım,\" diyor Deniz. \"Türkiye'de çok çay içeriz.\""],["They eat warm bread with butter and jam. Tom shows Deniz a map of the town. \"This is the harbour, this is the market, and this is my school.\"","Tereyağı ve reçelle sıcak ekmek yiyorlar. Tom, Deniz'e kasabanın bir haritasını gösteriyor. \"Burası liman, burası pazar, burası da benim okulum.\""],["\"And this is the lighthouse,\" says Deniz. Tom stops smiling. \"We don't go there,\" he says quietly.","\"Bu da deniz feneri,\" diyor Deniz. Tom'un gülümsemesi kayboluyor. \"Oraya gitmeyiz,\" diyor sessizce."]],"q":[["How old is Tom?",["ten","twelve","nineteen"],1,"'Tom is twelve.'"],["What do they eat?",["eggs and cheese","bread with butter and jam","fish"],1,"'warm bread with butter and jam'"],["How does Tom feel about the lighthouse?",["he loves it","he doesn't want to talk about it","he goes there every day"],1,"Gülümsemesi kayboluyor: 'We don't go there.'"]],"w":101},{"id":"A1-3","l":"A1","n":3,"t":"At the Harbour","p":[["In the afternoon, Deniz walks to the harbour. There are many boats. An old man is sitting on a boat. He is fixing a fishing net.","Öğleden sonra Deniz limana yürüyor. Çok sayıda tekne var. Yaşlı bir adam bir teknede oturuyor. Bir balık ağını tamir ediyor."],["\"Hello,\" says Deniz. \"Nice boat!\" The man laughs. \"Thank you. I'm Sam. I catch fish every morning. Are you new here?\"","\"Merhaba,\" diyor Deniz. \"Güzel tekne!\" Adam gülüyor. \"Teşekkürler. Ben Sam. Her sabah balık tutarım. Burada yeni misin?\""],["Deniz tells him about Izmir and the sea there. Then she asks about the lighthouse.","Deniz ona İzmir'i ve oradaki denizi anlatıyor. Sonra deniz fenerini soruyor."],["Sam looks at the old tower. \"It's closed. It's dark for thirty years now. The keeper was a friend of mine. His name was William.\" Sam is quiet for a long time.","Sam eski kuleye bakıyor. \"Kapalı. Otuz yıldır karanlık. Bekçisi bir arkadaşımdı. Adı William'dı.\" Sam uzun süre susuyor."]],"q":[["What is Sam doing?",["fixing a net","cooking fish","painting a boat"],0,"'He is fixing a fishing net.'"],["When does Sam catch fish?",["every evening","every morning","on Sundays"],1,"'I catch fish every morning.'"],["Who was William?",["Sam's brother","the lighthouse keeper","a teacher"],1,"'The keeper was a friend of mine. His name was William.'"]],"w":94},{"id":"A1-4","l":"A1","n":4,"t":"The English Class","p":[["On Monday, Deniz goes to an English class at the community centre. The teacher is Ms Lee. She is kind and funny.","Pazartesi Deniz toplum merkezindeki bir İngilizce dersine gidiyor. Öğretmen Bayan Lee. Nazik ve komik biri."],["There are eight students. Ana is from Brazil. She is a nurse. Yuki is from Japan. He likes photography.","Sekiz öğrenci var. Ana Brezilyalı. Hemşire. Yuki Japonyalı. Fotoğrafçılığı seviyor."],["Today the lesson is about family. Deniz talks about her mother, her father and her little brother, Efe. She misses them.","Bugünkü ders aile hakkında. Deniz annesinden, babasından ve küçük kardeşi Efe'den bahsediyor. Onları özlüyor."],["After class, Ana, Yuki and Deniz drink coffee together. \"Friday we have a picnic on the beach,\" says Ana. \"Come with us!\" Deniz smiles. She has new friends.","Dersten sonra Ana, Yuki ve Deniz birlikte kahve içiyor. \"Cuma günü plajda piknik yapıyoruz,\" diyor Ana. \"Bizimle gel!\" Deniz gülümsüyor. Yeni arkadaşları var."]],"q":[["Who is the teacher?",["Ms Lee","Ana","Mrs Penrose"],0,"'The teacher is Ms Lee.'"],["What is Ana's job?",["photographer","nurse","teacher"],1,"'She is a nurse.'"],["What is the plan for Friday?",["a party at school","a picnic on the beach","a trip to London"],1,"'Friday we have a picnic on the beach.'"]],"w":90},{"id":"A1-5","l":"A1","n":5,"t":"The Old Key","p":[["It is Sunday and it is raining. Deniz stays in her room. She writes a long message to her family in Izmir.","Pazar ve yağmur yağıyor. Deniz odasında kalıyor. İzmir'deki ailesine uzun bir mesaj yazıyor."],["Then she puts her books under the bed. One floorboard is loose. Under the board there is a small metal box.","Sonra kitaplarını yatağın altına koyuyor. Döşeme tahtalarından biri gevşek. Tahtanın altında küçük metal bir kutu var."],["In the box there is an old key. It is big and heavy. On the key there are two letters: W.L.","Kutunun içinde eski bir anahtar var. Büyük ve ağır. Anahtarın üzerinde iki harf var: W.L."],["Deniz looks at the key. Then she looks out of the window at the dark lighthouse. \"William,\" she says quietly. \"W is for William?\"","Deniz anahtara bakıyor. Sonra pencereden karanlık deniz fenerine bakıyor. \"William,\" diyor sessizce. \"W, William mı?\""]],"q":[["What is the weather like on Sunday?",["sunny","rainy","snowy"],1,"'it is raining'"],["Where does Deniz find the box?",["under a floorboard","in the bakery","on the beach"],0,"'Under the board there is a small metal box.'"],["What letters are on the key?",["D.P.","W.L.","S.W."],1,"'two letters: W.L.'"]],"w":88},{"id":"A2-1","l":"A2","n":1,"t":"A Job at Rosie's","p":[["Deniz needed some money, so she started working at Rosie's Café in the market square. Rosie was a cheerful woman with grey hair and a loud laugh.","Deniz'in biraz paraya ihtiyacı vardı, bu yüzden pazar meydanındaki Rosie's Café'de çalışmaya başladı. Rosie gri saçlı, kahkahası yüksek, neşeli bir kadındı."],["On her first day, Deniz made a lot of mistakes. She gave a customer tea instead of coffee, and she dropped two cups. \"Don't worry,\" said Rosie. \"Everyone makes mistakes on the first day.\"","İlk gününde Deniz bir sürü hata yaptı. Bir müşteriye kahve yerine çay verdi ve iki fincan düşürdü. \"Merak etme,\" dedi Rosie. \"İlk gün herkes hata yapar.\""],["By the end of the week, Deniz could make a perfect cappuccino. She learned the names of the regular customers and their favourite drinks.","Hafta sonunda Deniz mükemmel bir kapuçino yapabiliyordu. Müdavim müşterilerin adlarını ve en sevdikleri içecekleri öğrendi."],["One afternoon, she showed the old key to Rosie. Rosie's face changed. \"Where did you find that?\" she whispered. \"Put it away. Some people in this town don't like questions.\"","Bir öğleden sonra eski anahtarı Rosie'ye gösterdi. Rosie'nin yüzü değişti. \"Bunu nerede buldun?\" diye fısıldadı. \"Kaldır onu. Bu kasabada bazı insanlar sorulardan hoşlanmaz.\""]],"q":[["Why did Deniz start working?",["she was bored","she needed money","Rosie asked her"],1,"'Deniz needed some money'"],["What mistake did Deniz make on her first day?",["she gave tea instead of coffee","she was late","she broke the coffee machine"],0,"'She gave a customer tea instead of coffee'"],["How did Rosie react to the key?",["she laughed","she looked worried and told Deniz to hide it","she wanted to buy it"],1,"Yüzü değişti; anahtarı kaldırmasını söyledi."]],"w":115},{"id":"A2-2","l":"A2","n":2,"t":"Market Day","p":[["Every Saturday there was a market in Port Wren. People sold fish, vegetables, cheese, old books and antiques.","Port Wren'de her cumartesi pazar kurulurdu. İnsanlar balık, sebze, peynir, eski kitaplar ve antika satardı."],["Deniz and Yuki walked around the stalls. Yuki took photos of everything. At an antique stall, an old man was selling clocks, maps and keys.","Deniz ve Yuki tezgâhların arasında dolaştı. Yuki her şeyin fotoğrafını çekti. Bir antika tezgâhında yaşlı bir adam saatler, haritalar ve anahtarlar satıyordu."],["\"Do you buy old keys?\" Deniz asked, and she showed him her key. The man was Mr Hale. He looked at the letters W.L. and his hands started to shake.","\"Eski anahtar alıyor musunuz?\" diye sordu Deniz ve anahtarını gösterdi. Adam Bay Hale'di. W.L. harflerine baktı ve elleri titremeye başladı."],["\"It's not for sale,\" he said quickly. \"I mean, I don't want it. Go away, please.\" He closed his stall early that day. Yuki had a photo of his face. He looked afraid.","\"Satılık değil,\" dedi hızla. \"Yani, istemiyorum. Lütfen gidin.\" O gün tezgâhını erken kapattı. Yuki'nin elinde onun yüzünün bir fotoğrafı vardı. Korkmuş görünüyordu."]],"q":[["When was the market?",["every Saturday","every Sunday","every day"],0,"'Every Saturday there was a market'"],["What did Mr Hale sell?",["fish and vegetables","clocks, maps and keys","books only"],1,"'clocks, maps and keys'"],["How did Mr Hale feel when he saw the key?",["happy","afraid","bored"],1,"Elleri titredi, korkmuş görünüyordu."]],"w":106},{"id":"A2-3","l":"A2","n":3,"t":"Old Newspapers","p":[["On Monday, Deniz went to the small library next to the church. The librarian, Grace, was young and very helpful.","Pazartesi Deniz kilisenin yanındaki küçük kütüphaneye gitti. Kütüphaneci Grace gençti ve çok yardımseverdi."],["\"I want to read about the lighthouse,\" said Deniz. Grace brought a big box of old newspapers from 1994.","\"Deniz feneri hakkında okumak istiyorum,\" dedi Deniz. Grace 1994'ten kalma eski gazetelerle dolu büyük bir kutu getirdi."],["The headline said: KEEPER LOST IN STORM. On the night of the 3rd of November, there was a terrible storm. William Lowe, the lighthouse keeper, went out in his small boat. He never came back.","Manşette şöyle yazıyordu: BEKÇİ FIRTINADA KAYBOLDU. 3 Kasım gecesi korkunç bir fırtına vardı. Deniz feneri bekçisi William Lowe küçük teknesiyle denize açıldı. Bir daha geri dönmedi."],["\"William Lowe,\" said Deniz. \"W.L.!\" Grace looked at the key. \"Why did he go out in a storm?\" she asked. \"Nobody knows,\" said Deniz. \"But I want to find out.\"","\"William Lowe,\" dedi Deniz. \"W.L.!\" Grace anahtara baktı. \"Neden fırtınada denize açıldı?\" diye sordu. \"Kimse bilmiyor,\" dedi Deniz. \"Ama ben öğrenmek istiyorum.\""]],"q":[["What did Grace bring?",["old photos","old newspapers from 1994","a map"],1,"'old newspapers from 1994'"],["What happened on the 3rd of November 1994?",["the lighthouse opened","a terrible storm","a big party"],1,"'there was a terrible storm'"],["What does W.L. stand for?",["William Lowe","Wren Lighthouse","Walter Lee"],0,"Deniz 'William Lowe... W.L.!' diyor."]],"w":104},{"id":"A2-4","l":"A2","n":4,"t":"A Letter in a Book","p":[["Mrs Penrose asked Deniz to help clean the storage room behind the bakery. It was full of boxes, old furniture and dusty books.","Bayan Penrose, Deniz'den fırının arkasındaki depoyu temizlemesine yardım etmesini istedi. Oda kutular, eski mobilyalar ve tozlu kitaplarla doluydu."],["Deniz opened an old book about birds. A letter fell out. The envelope said: \"For M.\" The letter was short.","Deniz kuşlarla ilgili eski bir kitabı açtı. İçinden bir mektup düştü. Zarfın üstünde \"M. için\" yazıyordu. Mektup kısaydı."],["\"Dear M., I saw something terrible at sea last night. I wrote everything in the logbook. If something happens to me, find the logbook. The truth is there. Your brother, William.\"","\"Sevgili M., dün gece denizde korkunç bir şey gördüm. Her şeyi seyir defterine yazdım. Bana bir şey olursa seyir defterini bul. Gerçek orada. Kardeşin, William.\""],["Deniz read it twice. \"Brother?\" she thought. \"Who is M.?\" Then she heard a noise behind her. Mrs Penrose was standing at the door. Her eyes were full of tears.","Deniz iki kez okudu. \"Kardeş mi?\" diye düşündü. \"M. kim?\" Sonra arkasında bir ses duydu. Bayan Penrose kapıda duruyordu. Gözleri yaşlarla doluydu."]],"q":[["Where did Deniz find the letter?",["in a book about birds","under her bed","in the library"],0,"'an old book about birds. A letter fell out.'"],["What did William write everything in?",["a newspaper","the logbook","a diary on his phone"],1,"'I wrote everything in the logbook.'"],["How did Mrs Penrose look at the end?",["angry","she was crying","she was laughing"],1,"'Her eyes were full of tears.'"]],"w":104},{"id":"A2-5","l":"A2","n":5,"t":"Tom's Birthday","p":[["On Saturday it was Tom's thirteenth birthday. There was a party in the garden with a big chocolate cake, music and games.","Cumartesi Tom'un on üçüncü doğum günüydü. Bahçede büyük bir çikolatalı pasta, müzik ve oyunlarla bir parti vardı."],["Ana, Yuki and Sam came too. Tom got a new bike from his grandmother. He was very happy and rode it around the garden ten times.","Ana, Yuki ve Sam de geldi. Tom büyükannesinden yeni bir bisiklet aldı. Çok mutluydu ve bahçede on kez tur attı."],["Later, when everyone was eating cake, Mrs Penrose sat next to Deniz. \"My name is Mary,\" she said. \"M. is me. William was my little brother.\"","Daha sonra herkes pasta yerken Bayan Penrose Deniz'in yanına oturdu. \"Benim adım Mary,\" dedi. \"M. benim. William benim küçük kardeşimdi.\""],["\"For thirty years I didn't want to think about it,\" she said. \"But you found his key and his letter. Maybe it's time to find the logbook.\" Deniz held her hand. \"I'll help you,\" she said.","\"Otuz yıl boyunca bunu düşünmek istemedim,\" dedi. \"Ama sen onun anahtarını ve mektubunu buldun. Belki de seyir defterini bulma zamanı gelmiştir.\" Deniz elini tuttu. \"Sana yardım edeceğim,\" dedi."]],"q":[["How old was Tom on his birthday?",["twelve","thirteen","fourteen"],1,"'Tom's thirteenth birthday'"],["What did Tom get from his grandmother?",["a bike","a phone","a book"],0,"'Tom got a new bike from his grandmother.'"],["Who is M.?",["Ms Lee","Mrs Penrose (Mary)","Mr Hale"],1,"'My name is Mary. M. is me.'"]],"w":110},{"id":"B1-1","l":"B1","n":1,"t":"Where Is the Logbook?","p":[["The next morning, Deniz, Mary and Tom searched the lighthouse keeper's old things, but the logbook wasn't there. \"William kept it with him all the time,\" Mary said. \"He was very careful with it.\"","Ertesi sabah Deniz, Mary ve Tom fener bekçisinin eski eşyalarını aradılar ama seyir defteri orada değildi. \"William onu hep yanında taşırdı,\" dedi Mary. \"Ona çok dikkat ederdi.\""],["Deniz went down to the harbour to ask Sam. He was cleaning his boat, and he listened carefully while she told him about the letter.","Deniz, Sam'e sormak için limana indi. Sam teknesini temizliyordu ve Deniz ona mektubu anlatırken dikkatle dinledi."],["\"William had a small cabin in Wren Woods,\" Sam said at last. \"He used to go there when he wanted to be alone. In the weeks before the storm, he went there almost every day. I always thought it was strange.\"","\"William'ın Wren Ormanı'nda küçük bir kulübesi vardı,\" dedi Sam sonunda. \"Yalnız kalmak istediğinde oraya giderdi. Fırtınadan önceki haftalarda neredeyse her gün oraya gitti. Bunu hep tuhaf bulmuşumdur.\""],["\"Can you take me there?\" asked Deniz. Sam shook his head. \"My knees are too old for that path. But I can draw you a map.\"","\"Beni oraya götürebilir misin?\" diye sordu Deniz. Sam başını salladı. \"Dizlerim o patika için fazla yaşlı. Ama sana bir harita çizebilirim.\""]],"q":[["Why couldn't they find the logbook among William's things?",["it was stolen","William always kept it with him","Mary threw it away"],1,"'William kept it with him all the time.'"],["What did William do in the weeks before the storm?",["he went to his cabin almost every day","he stayed in the lighthouse","he travelled abroad"],0,"'he went there almost every day'"],["Why doesn't Sam go with Deniz?",["he is busy fishing","his knees are too old for the path","he is afraid"],1,"'My knees are too old for that path.'"]],"w":126},{"id":"B1-2","l":"B1","n":2,"t":"Lost in the Woods","p":[["On Saturday, Deniz, Ana and Tom set off early with Sam's map, sandwiches and plenty of water. The woods were beautiful, full of tall trees and bright green ferns.","Cumartesi günü Deniz, Ana ve Tom, Sam'in haritası, sandviçler ve bol suyla erkenden yola çıktı. Orman çok güzeldi; uzun ağaçlar ve parlak yeşil eğrelti otlarıyla doluydu."],["After two hours, however, the path disappeared under fallen leaves. They walked in circles for a long time. Tom's phone had no signal, and it was getting cold.","Ancak iki saat sonra patika düşen yaprakların altında kayboldu. Uzun süre daireler çizerek yürüdüler. Tom'un telefonu çekmiyordu ve hava soğumaya başlamıştı."],["\"Let's follow the river,\" suggested Ana. \"On Sam's map, the cabin is next to the river, near a waterfall.\" They walked slowly along the water, listening carefully.","\"Nehri takip edelim,\" diye önerdi Ana. \"Sam'in haritasında kulübe nehrin yanında, bir şelalenin yakınında.\" Suyun kenarından dikkatle dinleyerek yavaşça yürüdüler."],["Twenty minutes later, they heard the sound of falling water. Behind a curtain of ivy, they saw a small wooden building. \"We found it!\" shouted Tom.","Yirmi dakika sonra düşen su sesini duydular. Bir sarmaşık perdesinin arkasında küçük ahşap bir yapı gördüler. \"Bulduk!\" diye bağırdı Tom."]],"q":[["What problem did they have after two hours?",["they ran out of food","the path disappeared","Tom hurt his leg"],1,"'the path disappeared under fallen leaves'"],["Whose idea was it to follow the river?",["Tom's","Ana's","Deniz's"],1,"'suggested Ana'"],["Where was the cabin?",["on top of a hill","next to the river, near a waterfall","in the middle of a field"],1,"'next to the river, near a waterfall'"]],"w":110},{"id":"B1-3","l":"B1","n":3,"t":"The Cabin","p":[["The cabin was small and dark. The door was locked, and the windows were covered with dust. Deniz took out the old key with shaking hands. It fitted perfectly.","Kulübe küçük ve karanlıktı. Kapı kilitliydi, pencereler tozla kaplıydı. Deniz titreyen elleriyle eski anahtarı çıkardı. Tam olarak uydu."],["Inside there was a bed, a table, a chair and a shelf of books about the sea. Everything was covered in dust. It looked as if nobody had been there for thirty years.","İçeride bir yatak, bir masa, bir sandalye ve deniz hakkında kitaplarla dolu bir raf vardı. Her şey tozla kaplıydı. Sanki otuz yıldır oraya kimse gelmemiş gibiydi."],["Ana noticed that one of the floorboards under the table was a different colour. Tom pulled it up. Underneath there was a metal box wrapped in plastic.","Ana masanın altındaki döşeme tahtalarından birinin farklı renkte olduğunu fark etti. Tom tahtayı kaldırdı. Altında plastiğe sarılmış metal bir kutu vardı."],["Inside the box was a thick notebook with a blue cover. On the first page someone had written in neat handwriting: \"Logbook, Wren Point Lighthouse, 1994. W. Lowe.\"","Kutunun içinde mavi kapaklı kalın bir defter vardı. İlk sayfaya biri düzgün bir el yazısıyla şunu yazmıştı: \"Seyir Defteri, Wren Burnu Deniz Feneri, 1994. W. Lowe.\""]],"q":[["How did Deniz open the cabin door?",["she broke the window","with the old key","it was open"],1,"Eski anahtar kapıya tam uydu."],["Who noticed the different floorboard?",["Ana","Tom","Deniz"],0,"'Ana noticed that one of the floorboards...'"],["What was inside the metal box?",["money","the logbook","a map"],1,"'Logbook, Wren Point Lighthouse, 1994'"]],"w":117},{"id":"B1-4","l":"B1","n":4,"t":"What William Saw","p":[["That evening, they read the logbook at Mary's kitchen table. Most of the pages were about the weather, the boats and the lighthouse lamp. But the last pages were different.","O akşam seyir defterini Mary'nin mutfak masasında okudular. Sayfaların çoğu hava durumu, tekneler ve fener lambası hakkındaydı. Ama son sayfalar farklıydı."],["\"28 October. A large ship without lights stopped near Gull Island at 2 a.m. Men threw barrels into the sea. I could not see the name of the ship, but I saw the logo of Harbour Holdings on one of the boxes.\"","\"28 Ekim. Işıksız büyük bir gemi gece saat 2'de Martı Adası yakınında durdu. Adamlar denize variller attı. Geminin adını göremedim ama kutulardan birinin üzerinde Harbour Holdings'in logosunu gördüm.\""],["\"2 November. I told someone at the company what I saw. He offered me money to forget it. I refused. Tomorrow I will take my boat to the island and get proof.\"","\"2 Kasım. Şirketten birine gördüklerimi anlattım. Unutmam için bana para teklif etti. Reddettim. Yarın teknemle adaya gidip kanıt bulacağım.\""],["The next day was the 3rd of November, the night of the storm. Mary put her hands over her face. \"He didn't go out because he was careless,\" she said. \"He went out because he was brave.\"","Ertesi gün 3 Kasım'dı, fırtına gecesi. Mary ellerini yüzüne kapadı. \"Dikkatsiz olduğu için denize açılmadı,\" dedi. \"Cesur olduğu için açıldı.\""]],"q":[["What did William see near Gull Island?",["a shipwreck","men throwing barrels into the sea","a whale"],1,"'Men threw barrels into the sea.'"],["What did the company offer William?",["a job","money to forget it","a new boat"],1,"'He offered me money to forget it.'"],["Why did William go out on the night of the storm, according to the logbook?",["to go fishing","to get proof from the island","to visit a friend"],1,"'I will take my boat to the island and get proof.'"]],"w":141},{"id":"B1-5","l":"B1","n":5,"t":"The Break-in","p":[["On Monday, Deniz came home from the café and found her bedroom door open. Her clothes were all over the floor, and her drawers had been emptied.","Pazartesi günü Deniz kafeden eve geldiğinde yatak odasının kapısını açık buldu. Kıyafetleri yerlere saçılmış, çekmeceleri boşaltılmıştı."],["Her laptop and her money were still there. Only one thing was missing: the blue logbook.","Dizüstü bilgisayarı ve parası hâlâ oradaydı. Tek bir şey eksikti: mavi seyir defteri."],["Mary called the police, but the officer didn't seem very interested. \"An old notebook? Are you sure you didn't just lose it?\" he asked.","Mary polisi aradı ama memur pek ilgili görünmedi. \"Eski bir defter mi? Sadece kaybetmediğinizden emin misiniz?\" diye sordu."],["When he left, Deniz smiled for the first time that evening. She took out her phone. \"They took the book,\" she said, \"but on Saturday night I photographed every single page.\"","Memur gidince Deniz o akşam ilk kez gülümsedi. Telefonunu çıkardı. \"Defteri aldılar,\" dedi, \"ama cumartesi gecesi her bir sayfanın fotoğrafını çektim.\""]],"q":[["What was stolen from Deniz's room?",["her laptop","her money","the logbook"],2,"'Only one thing was missing: the blue logbook.'"],["How did the police officer react?",["he was very worried","he didn't seem very interested","he arrested someone"],1,"'the officer didn't seem very interested'"],["Why did Deniz smile?",["she had photos of every page","the police found the book","she had another copy at the café"],0,"'I photographed every single page.'"]],"w":98},{"id":"B2-1","l":"B2","n":1,"t":"The Town Meeting","p":[["A week later, posters appeared all over Port Wren: PUBLIC MEETING – THE FUTURE OF WREN POINT. Harbour Holdings had announced plans to build a luxury hotel on the headland, which meant the lighthouse would be demolished.","Bir hafta sonra Port Wren'in her yerinde afişler belirdi: HALK TOPLANTISI – WREN BURNU'NUN GELECEĞİ. Harbour Holdings burun üzerinde lüks bir otel inşa etme planlarını açıklamıştı; bu da deniz fenerinin yıkılacağı anlamına geliyordu."],["The town hall was packed. A smartly dressed man from the company, Mr Crane, gave a confident presentation full of promises: two hundred new jobs, more tourists and money for the local school.","Belediye binası tıklım tıklımdı. Şirketten şık giyimli bir adam, Bay Crane, vaatlerle dolu kendinden emin bir sunum yaptı: iki yüz yeni iş, daha fazla turist ve yerel okul için para."],["Many people seemed convinced. Rosie, however, stood up and asked why a company that cared so much about the town had never repaired the harbour wall, which it had owned for twenty years.","Birçok kişi ikna olmuş görünüyordu. Ancak Rosie ayağa kalktı ve kasabayı bu kadar önemseyen bir şirketin yirmi yıldır sahibi olduğu liman duvarını neden hiç onarmadığını sordu."],["Mr Crane smiled politely and avoided the question. Deniz noticed something else: in the back row, Mr Hale was sitting with his head down, unable to look at anyone.","Bay Crane kibarca gülümsedi ve sorudan kaçtı. Deniz başka bir şey fark etti: arka sırada Bay Hale, başı önünde, kimsenin yüzüne bakamadan oturuyordu."]],"q":[["What did Harbour Holdings want to build?",["a new harbour","a luxury hotel","a school"],1,"'a luxury hotel on the headland'"],["What did Rosie point out?",["the company had never repaired the harbour wall","the hotel was too small","tourists don't like hotels"],0,"Liman duvarını yirmi yıldır onarmamışlardı."],["What did Deniz notice about Mr Hale?",["he was asking questions","he couldn't look at anyone","he was very angry"],1,"'unable to look at anyone'"]],"w":132},{"id":"B2-2","l":"B2","n":2,"t":"The Journalist","p":[["Deniz took the train to the nearest city to visit the offices of the regional newspaper. A journalist called Priya Sharma agreed to meet her for fifteen minutes.","Deniz bölge gazetesinin bürosunu ziyaret etmek için en yakın şehre trenle gitti. Priya Sharma adında bir gazeteci onunla on beş dakika görüşmeyi kabul etti."],["Priya listened, scrolling through the photos of the logbook. Then she sighed. \"It's a fascinating story, but it's thirty years old, and these are the notes of a man who can't be interviewed. Their lawyers would destroy us.\"","Priya dinledi, seyir defterinin fotoğraflarına göz gezdirdi. Sonra iç çekti. \"Büyüleyici bir hikâye ama otuz yıllık ve bunlar röportaj yapılamayacak bir adamın notları. Avukatları bizi yerle bir eder.\""],["\"So what would you need?\" asked Deniz. \"A living witness,\" Priya replied, \"or physical evidence. Ideally both. Find me either of those, and I'll write the story.\"","\"Peki neye ihtiyacın var?\" diye sordu Deniz. \"Yaşayan bir tanığa,\" diye cevap verdi Priya, \"ya da fiziksel kanıta. İdeal olarak ikisine de. Bunlardan birini bul, hikâyeyi yazarım.\""],["On the train home, Deniz thought about Mr Hale's shaking hands at the market. If anyone in Port Wren remembered what had happened in 1994, it was him.","Eve dönerken trende Deniz, Bay Hale'in pazardaki titreyen ellerini düşündü. Port Wren'de 1994'te olanları hatırlayan biri varsa, o oydu."]],"q":[["Why was Priya hesitant at first?",["she didn't believe Deniz","the story was old and could cause legal problems","she was too busy"],1,"Otuz yıllık; avukatlar sorun çıkarır."],["What did Priya need to write the story?",["a living witness or physical evidence","more photos","money"],0,"'A living witness, or physical evidence.'"],["Who did Deniz think could be a witness?",["Sam","Mr Hale","Rosie"],1,"Bay Hale'i düşündü."]],"w":121},{"id":"B2-3","l":"B2","n":3,"t":"Mr Hale's Confession","p":[["Mr Hale lived alone in a narrow house full of clocks. When Deniz knocked, he almost closed the door, but Mary was standing behind her, and he couldn't refuse her.","Bay Hale saatlerle dolu dar bir evde yalnız yaşıyordu. Deniz kapıyı çaldığında neredeyse kapıyı kapatacaktı ama Mary onun arkasında duruyordu ve onu geri çeviremedi."],["Over a pot of tea that nobody drank, he told them everything. In 1994 he had worked as a clerk at Harbour Holdings. He had seen documents about \"special cargo\" that was never recorded officially.","Kimsenin içmediği bir demlik çayın başında onlara her şeyi anlattı. 1994'te Harbour Holdings'te memur olarak çalışmıştı. Hiçbir zaman resmî olarak kaydedilmeyen \"özel yük\" ile ilgili belgeler görmüştü."],["After William disappeared, a manager had given him an envelope full of cash and made it clear that he should keep quiet. \"I had a sick wife and no savings,\" he said. \"I told myself it wouldn't change anything. I've regretted it every day since.\"","William kaybolduktan sonra bir müdür ona nakit dolu bir zarf vermiş ve sessiz kalması gerektiğini açıkça belirtmişti. \"Hasta bir karım vardı ve hiç birikimim yoktu,\" dedi. \"Kendime bunun hiçbir şeyi değiştirmeyeceğini söyledim. O günden beri her gün pişmanlık duyuyorum.\""],["Mary was silent for a long time. Then she put her hand on his arm. \"Then help us now, Arthur,\" she said. He nodded slowly. \"I still have copies of some of those documents.\"","Mary uzun süre sessiz kaldı. Sonra elini onun koluna koydu. \"O zaman şimdi bize yardım et, Arthur,\" dedi. Adam yavaşça başını salladı. \"O belgelerin bazılarının kopyaları hâlâ bende.\""]],"q":[["Why did Mr Hale let them in?",["Deniz paid him","he couldn't refuse Mary","the police were with them"],1,"'he couldn't refuse her'"],["What was Mr Hale's job in 1994?",["a fisherman","a clerk at Harbour Holdings","a police officer"],1,"'a clerk at Harbour Holdings'"],["Why did he accept the money?",["he wanted a new house","his wife was sick and he had no savings","he didn't believe William"],1,"'I had a sick wife and no savings.'"]],"w":144},{"id":"B2-4","l":"B2","n":4,"t":"Pressure","p":[["News travels fast in a small town. Two days later, Rosie received a letter from her landlord, a property company owned by Harbour Holdings, announcing that her rent would double from next month.","Küçük bir kasabada haberler hızlı yayılır. İki gün sonra Rosie, Harbour Holdings'e ait bir emlak şirketi olan ev sahibinden kirasının gelecek aydan itibaren iki katına çıkacağını bildiren bir mektup aldı."],["That same evening, Deniz got a polite but worrying email from her language school. Someone had made a complaint about her, and her visa sponsorship was being \"reviewed\".","Aynı akşam Deniz, dil okulundan kibar ama endişe verici bir e-posta aldı. Biri onun hakkında şikâyette bulunmuştu ve vize sponsorluğu \"gözden geçiriliyordu\"."],["Deniz lay awake all night. If she lost her visa, she would have to go home. If she continued, she might cost Rosie her café. Wouldn't it be easier to give the photos to Priya anonymously and step back?","Deniz bütün gece uyuyamadı. Vizesini kaybederse eve dönmek zorunda kalacaktı. Devam ederse Rosie'nin kafesini kaybetmesine neden olabilirdi. Fotoğrafları Priya'ya isimsiz olarak verip geri çekilmek daha kolay olmaz mıydı?"],["In the morning, Rosie found her sitting outside the café. \"Don't you dare give up because of me,\" Rosie said firmly. \"I've survived worse landlords than these. William didn't stop, and neither should you.\"","Sabah Rosie onu kafenin önünde otururken buldu. \"Sakın benim yüzümden vazgeçme,\" dedi Rosie kararlı bir şekilde. \"Bunlardan beter ev sahiplerini atlattım. William durmadı, sen de durmamalısın.\""]],"q":[["What happened to Rosie's rent?",["it was cancelled","it would double","it stayed the same"],1,"'her rent would double'"],["What was the problem with Deniz's visa?",["it had expired","her sponsorship was being reviewed after a complaint","she lost her passport"],1,"Şikâyet sonrası sponsorluk gözden geçiriliyordu."],["What did Rosie tell Deniz?",["to stop for her sake","not to give up because of her","to leave town"],1,"'Don't you dare give up because of me.'"]],"w":134},{"id":"B2-5","l":"B2","n":5,"t":"Going Public","p":[["With Mr Hale's documents and the photos of the logbook, Priya finally had enough. Her article appeared on the front page under the headline: DID A COMPANY'S SECRET COST A KEEPER HIS LIFE?","Bay Hale'in belgeleri ve seyir defterinin fotoğraflarıyla Priya'nın sonunda yeterli malzemesi oldu. Makalesi ön sayfada şu manşetle çıktı: BİR ŞİRKETİN SIRRI BİR BEKÇİNİN HAYATINA MI MAL OLDU?"],["Within hours the story had been shared thousands of times. National television called. Harbour Holdings issued a short statement denying everything and threatening legal action.","Birkaç saat içinde haber binlerce kez paylaşıldı. Ulusal televizyon aradı. Harbour Holdings her şeyi inkâr eden ve hukuki işlem başlatmakla tehdit eden kısa bir açıklama yaptı."],["Not everyone in Port Wren was pleased. Some people had been looking forward to the new jobs, and a few of them told Deniz, quite rudely, that outsiders should mind their own business.","Port Wren'deki herkes memnun değildi. Bazıları yeni işleri dört gözle bekliyordu ve birkaçı Deniz'e oldukça kaba bir şekilde yabancıların kendi işine bakması gerektiğini söyledi."],["But that evening, more than a hundred people gathered on the headland with candles, beneath the dark lighthouse. Tom held a sign he had painted himself: LIGHT IT AGAIN.","Ama o akşam yüzden fazla kişi, karanlık deniz fenerinin altında, burunda ellerinde mumlarla toplandı. Tom kendi boyadığı bir pankart tutuyordu: YENİDEN YAK."]],"q":[["What did Priya finally have enough of?",["evidence","money","time"],0,"Belgeler ve fotoğraflarla yeterli kanıt."],["How did Harbour Holdings respond?",["they apologized","they denied everything and threatened legal action","they closed the company"],1,"'denying everything and threatening legal action'"],["What did Tom's sign say?",["SAVE OUR JOBS","LIGHT IT AGAIN","GO HOME"],1,"'LIGHT IT AGAIN'"]],"w":120},{"id":"C1-1","l":"C1","n":1,"t":"Crossing to Gull Island","p":[["Priya's article had stirred up a storm of its own, but Harbour Holdings' lawyers were quick to point out that a dead man's notebook proved nothing. What they needed, Deniz realised, was the very thing William had gone looking for thirty years earlier: physical proof.","Priya'nın makalesi kendi çapında bir fırtına koparmıştı ama Harbour Holdings'in avukatları ölü bir adamın defterinin hiçbir şey kanıtlamadığını hemen belirttiler. Deniz, ihtiyaç duydukları şeyin William'ın otuz yıl önce aramaya çıktığı şeyin ta kendisi olduğunu fark etti: fiziksel kanıt."],["Sam, who had sworn he would never sail past the headland again, surprised everyone by offering to take her. \"I let William go out alone once,\" he said gruffly. \"I'm not making that mistake twice.\"","Burnun ötesine bir daha asla açılmayacağına yemin etmiş olan Sam, onu götürmeyi teklif ederek herkesi şaşırttı. \"Bir kere William'ın tek başına gitmesine izin verdim,\" dedi sert bir sesle. \"Aynı hatayı iki kez yapmayacağım.\""],["They set off at dawn, with Yuki and his camera squeezed into the stern. The sea was deceptively calm, but Sam kept glancing at the sky, reading signs in the clouds that Deniz could barely make out.","Şafakta yola çıktılar; Yuki ve kamerası kıç tarafına sıkışmıştı. Deniz aldatıcı biçimde sakindi ama Sam sürekli gökyüzüne göz atıyor, bulutlarda Deniz'in zar zor seçebildiği işaretleri okuyordu."],["Gull Island turned out to be little more than a jagged ridge of rock, deserted except for thousands of screaming seabirds. Yet as they drew closer, Deniz noticed something odd: on the northern side, where the cliffs dropped into a narrow cove, the water was an unnatural shade of brown.","Martı Adası, binlerce çığlık atan deniz kuşu dışında ıssız, sivri bir kaya sırtından ibaretti. Yine de yaklaştıkça Deniz tuhaf bir şey fark etti: kuzey tarafında, kayalıkların dar bir koya indiği yerde su doğal olmayan kahverengi bir tondaydı."]],"q":[["Why did the company's lawyers dismiss the logbook?",["it was written in code","it was the notebook of a man who could no longer be questioned","it had been forged"],1,"'a dead man's notebook proved nothing'"],["What motivated Sam to make the journey?",["he wanted to be on television","he regretted letting William go alone","Deniz paid him well"],1,"'I let William go out alone once... not making that mistake twice.'"],["What did Deniz notice in the cove?",["a sunken ship","unnaturally brown water","a hidden cave"],1,"'the water was an unnatural shade of brown'"]],"w":167},{"id":"C1-2","l":"C1","n":2,"t":"The Barrels","p":[["Sam steered the boat into the cove as far as he dared, and Deniz waded ashore, the icy water numbing her legs within seconds. Wedged between the rocks, half-buried in sand and seaweed, were the rusted remains of at least a dozen metal barrels.","Sam tekneyi cesaret edebildiği kadar koyun içine sürdü ve Deniz suyun içinden yürüyerek kıyıya çıktı; buz gibi su birkaç saniye içinde bacaklarını uyuşturdu. Kayaların arasına sıkışmış, yarısı kum ve yosuna gömülü en az bir düzine metal varilin paslı kalıntıları duruyordu."],["Most had split open long ago, and a thick, tar-like substance had seeped into the surrounding rocks. Nothing grew there. Even the gulls, which covered every other inch of the island, kept their distance.","Çoğu uzun zaman önce yarılmıştı ve kalın, katran benzeri bir madde etraftaki kayalara sızmıştı. Orada hiçbir şey yetişmiyordu. Adanın her karışını kaplayan martılar bile mesafelerini koruyordu."],["Yuki photographed everything methodically, making sure each image included a measuring tape and the GPS coordinates. Then Deniz spotted it: on one of the less corroded barrels, the faded outline of a stencilled logo – a wren perched on an anchor.","Yuki her şeyi titizlikle fotoğrafladı ve her karede bir şerit metre ile GPS koordinatlarının yer almasını sağladı. Sonra Deniz onu gördü: daha az aşınmış varillerden birinin üzerinde, şablonla basılmış bir logonun solmuş hatları – bir çapanın üzerine konmuş bir çalıkuşu."],["\"That's the old Harbour Holdings logo,\" Sam said quietly when she showed him the photograph. \"They changed it in '95. Funny, that.\" Using gloves and a glass jar Tom had insisted she take, Deniz collected a sample of the sludge before the tide began to turn.","\"Bu Harbour Holdings'in eski logosu,\" dedi Sam, Deniz ona fotoğrafı gösterince sessizce. \"'95'te değiştirdiler. Tuhaf, değil mi?\" Deniz, Tom'un yanına almasında ısrar ettiği eldivenler ve cam kavanozla, gelgit dönmeye başlamadan önce çamurdan bir örnek aldı."]],"q":[["Why did Yuki include a measuring tape and GPS coordinates in his photos?",["for artistic effect","to make the photos usable as evidence","because Sam asked him to"],1,"Her karede ölçü ve konum: kanıt değeri taşısın diye."],["What suggested that the area was polluted?",["dead fish everywhere","nothing grew and even the gulls avoided it","a strong smell of oil"],1,"'Nothing grew there... the gulls kept their distance.'"],["Why was the logo significant?",["it was the company's old logo, replaced in 1995","it belonged to a different company","it was painted recently"],0,"'They changed it in '95.'"]],"w":165},{"id":"C1-3","l":"C1","n":3,"t":"Dr Morgan's Results","p":[["Dr Helen Morgan, a marine chemist at the university, agreed to analyse the sample – on the condition that the results would be published regardless of what they showed. \"If it turns out to be harmless,\" she warned, \"your campaign goes down with it.\"","Üniversitede deniz kimyacısı olan Dr. Helen Morgan, sonuçlar ne gösterirse göstersin yayımlanması koşuluyla örneği analiz etmeyi kabul etti. \"Zararsız çıkarsa,\" diye uyardı, \"kampanyanız da onunla birlikte batar.\""],["The ten days that followed were among the longest of Deniz's life. She threw herself into her studies and extra shifts at the café, but every time her phone buzzed, her heart skipped a beat.","Ardından gelen on gün Deniz'in hayatının en uzun günleri arasındaydı. Kendini derslerine ve kafedeki ek vardiyalara verdi ama telefonu her titrediğinde kalbi teklerdi."],["When the report finally arrived, it was even worse than she had feared. The sludge contained heavy metals and industrial solvents at concentrations hundreds of times above the legal limit – substances that had been banned from disposal at sea since the early nineties.","Rapor sonunda geldiğinde korktuğundan bile kötüydü. Çamur, yasal sınırın yüzlerce kat üzerinde konsantrasyonlarda ağır metaller ve endüstriyel çözücüler içeriyordu – doksanların başından beri denize boşaltılması yasaklanmış maddeler."],["Dr Morgan went further. Samples she had taken from mussels along the coast showed traces of the same compounds. \"This isn't just a historical scandal,\" she told a packed press conference. \"It's an ongoing environmental hazard, and somebody knew about it all along.\"","Dr. Morgan daha da ileri gitti. Kıyı boyunca midyelerden aldığı örneklerde aynı bileşiklerin izleri vardı. \"Bu sadece tarihî bir skandal değil,\" dedi tıklım tıklım bir basın toplantısında. \"Bu süregelen bir çevre tehlikesi ve birileri baştan beri bunu biliyordu.\""]],"q":[["What was Dr Morgan's condition for doing the analysis?",["she would be paid","the results would be published whatever they showed","her name would be kept secret"],1,"'published regardless of what they showed'"],["What did the report reveal?",["the sludge was harmless","heavy metals and solvents far above legal limits","only traces of oil"],1,"Yasal sınırın yüzlerce kat üzerinde."],["Why did Dr Morgan say it was 'not just a historical scandal'?",["the pollution was still affecting marine life","the company still existed","the barrels were new"],0,"Midyelerde aynı bileşiklerin izleri vardı."]],"w":166},{"id":"C1-4","l":"C1","n":4,"t":"The Inquiry","p":[["Under mounting public pressure, the county council launched a formal inquiry. The hearing was held in a wood-panelled chamber, and Deniz, who had never so much as set foot in a courtroom, was called as a witness.","Artan kamuoyu baskısı altında il meclisi resmî bir soruşturma başlattı. Duruşma ahşap kaplı bir salonda yapıldı ve mahkeme salonuna adımını bile atmamış olan Deniz tanık olarak çağrıldı."],["The company's barrister, a silver-haired man with an icy smile, did his utmost to discredit her. Wasn't it true that she was a foreign student with no scientific training? Hadn't she obtained the logbook in highly irregular circumstances? Was she perhaps seeking publicity?","Şirketin avukatı, gümüş saçlı ve buz gibi gülümsemeli bir adam, onu itibarsızlaştırmak için elinden geleni yaptı. Bilimsel eğitimi olmayan yabancı bir öğrenci olduğu doğru değil miydi? Seyir defterini son derece usulsüz koşullar altında elde etmemiş miydi? Belki de reklam peşinde değil miydi?"],["Deniz felt her cheeks burn, but she kept her voice steady. \"I'm not a scientist,\" she replied, \"which is precisely why I asked one. And with respect, the circumstances in which I found the logbook are far less irregular than the circumstances in which those barrels ended up on Gull Island.\"","Deniz yanaklarının yandığını hissetti ama sesini sabit tuttu. \"Bilim insanı değilim,\" diye cevap verdi, \"tam da bu yüzden bir bilim insanına sordum. Ve saygılarımla, seyir defterini bulduğum koşullar, o varillerin Martı Adası'na varma koşullarından çok daha az usulsüz.\""],["A murmur of approval ran through the public gallery. Then Arthur Hale took the stand and, in a trembling voice, confirmed every detail of the payments. By the end of the day, the barrister's smile had vanished.","Dinleyici sıralarında bir onay mırıltısı dolaştı. Sonra Arthur Hale kürsüye çıktı ve titreyen bir sesle ödemelerin her ayrıntısını doğruladı. Günün sonunda avukatın gülümsemesi kaybolmuştu."]],"q":[["How did the company's barrister try to weaken Deniz's testimony?",["by questioning her background and motives","by presenting new evidence","by refusing to ask questions"],0,"Yabancı öğrenci, bilimsel eğitimi yok, reklam peşinde mi?"],["What was the point of Deniz's reply about 'irregular circumstances'?",["she admitted she had stolen the logbook","the company's actions were far more questionable than hers","she apologised to the court"],1,"Asıl usulsüzlük varillerin adaya gelişiydi."],["What effect did Arthur Hale's testimony have?",["it confirmed the payments","it contradicted Deniz","it was rejected by the court"],0,"'confirmed every detail of the payments'"]],"w":168},{"id":"C1-5","l":"C1","n":5,"t":"A Letter from Scotland","p":[["A week after the hearing, a letter arrived at the bakery addressed in shaky, old-fashioned handwriting to \"Miss Deniz Yılmaz, c/o Mrs M. Penrose\". The postmark was from a village on the Isle of Skye.","Duruşmadan bir hafta sonra fırına titrek, eski usul bir el yazısıyla \"Bayan Deniz Yılmaz, Bayan M. Penrose eliyle\" adresli bir mektup geldi. Posta damgası Skye Adası'ndaki bir köydendi."],["\"I saw your face on the television,\" it began, \"holding a key I had not seen for thirty years. I owe you an explanation, and I owe my sister a great deal more than that.\"","\"Yüzünü televizyonda gördüm,\" diye başlıyordu, \"otuz yıldır görmediğim bir anahtarı tutarken. Sana bir açıklama borçluyum, kız kardeşime ise bundan çok daha fazlasını.\""],["The writer explained that on the night of the storm his boat had been wrecked on the rocks, but he had been pulled from the water by the crew of a Scottish trawler. Badly injured, and convinced that the men who had threatened him would try again, he had let the world believe he was dead and started a new life under another name.","Yazan kişi, fırtına gecesi teknesinin kayalara çarparak parçalandığını ama bir İskoç balıkçı teknesinin mürettebatı tarafından sudan çıkarıldığını anlatıyordu. Ağır yaralı ve kendisini tehdit eden adamların yeniden deneyeceğine inanmış hâlde, dünyanın onun öldüğüne inanmasına izin vermiş ve başka bir isim altında yeni bir hayata başlamıştı."],["\"Every year I told myself I would come home,\" the letter ended, \"and every year my courage failed me. Please tell Mary I am sorry. W.\" Deniz read it three times before she could bring herself to walk upstairs and knock on Mary's door.","\"Her yıl kendime eve döneceğimi söyledim,\" diye bitiyordu mektup, \"ve her yıl cesaretim beni yarı yolda bıraktı. Lütfen Mary'ye üzgün olduğumu söyle. W.\" Deniz, yukarı çıkıp Mary'nin kapısını çalmaya kendini ikna edebilmeden önce mektubu üç kez okudu."]],"q":[["How did William learn about Deniz?",["Sam told him","he saw her on television","he read the logbook"],1,"'I saw your face on the television'"],["How did William survive the storm?",["he swam to Gull Island","a Scottish trawler crew rescued him","he never left the harbour"],1,"'pulled from the water by the crew of a Scottish trawler'"],["Why did he let people believe he was dead?",["he wanted a new career","he feared the men who had threatened him","he had lost his memory"],1,"Kendisini tehdit edenlerin yeniden deneyeceğinden korktu."]],"w":178},{"id":"C2-1","l":"C2","n":1,"t":"The Man on Skye","p":[["Mary refused to fly, so she and Deniz took the overnight sleeper north and then a series of ever smaller buses, until the road dwindled into a single-track lane winding between heather and grey water. Neither of them spoke much; there was too much to say and no way of beginning.","Mary uçmayı reddetti, bu yüzden o ve Deniz kuzeye giden yataklı gece trenine, ardından giderek küçülen bir dizi otobüse bindiler; ta ki yol, funda ile gri sular arasında kıvrılan tek şeritli bir patikaya dönüşene kadar. İkisi de pek konuşmadı; söylenecek çok şey vardı ama başlamanın bir yolu yoktu."],["The cottage stood alone at the end of a promontory, and from its window, Deniz noticed with a jolt, one could see a small lighthouse blinking across the sound. Whatever else William had abandoned, he had never quite let go of the light.","Kulübe bir burnun ucunda tek başına duruyordu ve Deniz irkilerek fark etti ki, penceresinden boğazın karşısında yanıp sönen küçük bir deniz feneri görülebiliyordu. William başka neyi geride bırakmış olursa olsun, ışıktan hiçbir zaman tam anlamıyla vazgeçmemişti."],["The man who opened the door was stooped and weather-beaten, but his eyes were unmistakably Mary's. For a long moment the two of them simply stood there, seventy years of shared childhood and thirty of silence hanging between them.","Kapıyı açan adam kamburlaşmış ve rüzgârdan yıpranmıştı ama gözleri hiç şüphesiz Mary'nin gözleriydi. Uzun bir an ikisi de öylece durdu; aralarında yetmiş yıllık ortak bir çocukluk ve otuz yıllık bir sessizlik asılı duruyordu."],["It was Mary who broke it. \"You always were hopeless at writing letters, Will,\" she said, and her voice cracked on the last word. Deniz slipped quietly out into the garden, sensing that whatever passed between them next was not hers to witness.","Sessizliği bozan Mary oldu. \"Mektup yazmakta hep berbattın, Will,\" dedi ve sesi son kelimede çatallandı. Deniz, aralarında bundan sonra geçecek her neyse onun tanık olacağı bir şey olmadığını sezerek sessizce bahçeye süzüldü."]],"q":[["What detail about the cottage struck Deniz?",["it had no electricity","a lighthouse was visible from its window","it was built of wood"],1,"Pencereden bir deniz feneri görünüyordu."],["What does 'seventy years of shared childhood and thirty of silence hanging between them' convey?",["they had nothing in common","the weight of their long bond and long separation","they were both very old and tired"],1,"Uzun bağ ve uzun ayrılığın ağırlığı."],["Why did Deniz go out into the garden?",["she felt the moment belonged to the siblings alone","she wanted to take photos","William asked her to leave"],0,"'not hers to witness'"]],"w":176},{"id":"C2-2","l":"C2","n":2,"t":"The Verdict","p":[["William's testimony, delivered by video link in a halting but lucid voice, proved to be the final nail in the coffin. He named the manager who had threatened him, described the cargo in harrowing detail and identified the ship from photographs the inquiry had obtained from maritime archives.","William'ın görüntülü bağlantıyla, duraksayan ama berrak bir sesle verdiği ifade tabuta çakılan son çivi oldu. Kendisini tehdit eden müdürün adını verdi, yükü tüyler ürpertici ayrıntılarla anlattı ve soruşturmanın denizcilik arşivlerinden elde ettiği fotoğraflardan gemiyi teşhis etti."],["The inquiry's report, published three months later, pulled no punches. It concluded that Harbour Holdings had systematically disposed of hazardous waste at sea over a period of at least four years, and that senior figures had sought to conceal it through bribery and intimidation.","Üç ay sonra yayımlanan soruşturma raporu lafı hiç dolandırmadı. Harbour Holdings'in en az dört yıllık bir süre boyunca tehlikeli atıkları sistematik olarak denize boşalttığı ve üst düzey isimlerin bunu rüşvet ve yıldırma yoluyla gizlemeye çalıştığı sonucuna vardı."],["Although the passage of time ruled out some criminal charges, the company was ordered to fund a full clean-up of Gull Island and the surrounding waters – an operation expected to cost tens of millions. Within a week, its share price had collapsed, and the hotel project was quietly withdrawn.","Aradan geçen zaman bazı cezai suçlamaları imkânsız kılsa da şirkete Martı Adası ve çevresindeki suların tamamen temizlenmesini finanse etmesi emredildi – on milyonlara mal olması beklenen bir operasyon. Bir hafta içinde hisse fiyatı çöktü ve otel projesi sessiz sedasız geri çekildi."],["Deniz heard the news while wiping tables at Rosie's. There was no cheering, no champagne – just Rosie switching off the radio, sitting down heavily and saying, to no one in particular, \"Well. That's that, then.\" It struck Deniz that justice, when it finally arrives, is often strangely undramatic.","Deniz haberi Rosie's'de masaları silerken duydu. Ne tezahürat oldu ne şampanya – sadece Rosie radyoyu kapattı, ağır ağır oturdu ve kimseye hitap etmeden \"Eh. Demek bu kadar,\" dedi. Deniz'e, adaletin sonunda geldiğinde çoğu zaman tuhaf biçimde dramatik olmaktan uzak olduğu geldi."]],"q":[["What does 'the final nail in the coffin' mean here?",["the decisive blow to the company's defence","William's health was failing","the inquiry was cancelled"],0,"Şirketin savunmasına indirilen son, belirleyici darbe."],["Why couldn't all criminal charges be brought?",["there was no evidence","too much time had passed","the company had moved abroad"],1,"'the passage of time ruled out some criminal charges'"],["What observation does Deniz make at the end?",["justice is often quietly undramatic when it comes","Rosie was disappointed","the town wanted a big celebration"],0,"Adalet çoğu zaman sessiz gelir."]],"w":191},{"id":"C2-3","l":"C2","n":3,"t":"A Light Worth Keeping","p":[["With the hotel scheme dead, the question became what to do with the lighthouse itself. Decades of neglect had taken their toll: the lantern glass was shattered, the iron staircase was rusted through in places, and the engineers' estimate made even the most ardent supporters wince.","Otel projesi suya düşünce asıl soru deniz fenerinin kendisiyle ne yapılacağı oldu. Onlarca yıllık ihmal bedelini ödetmişti: fener camı paramparçaydı, demir merdiven yer yer paslanıp delinmişti ve mühendislerin tahmini en hararetli destekçileri bile yüzünü buruşturtacak kadar yüksekti."],["A restoration trust was formed, with Grace as its unlikely but formidable treasurer. Ana organised a sponsored swim; Yuki's photographs of Gull Island were exhibited in London and auctioned; Tom and his classmates raised a surprising sum selling hand-painted postcards of the lighthouse.","Bir restorasyon vakfı kuruldu; Grace beklenmedik ama son derece yetkin bir saymandı. Ana sponsorlu bir yüzme etkinliği düzenledi; Yuki'nin Martı Adası fotoğrafları Londra'da sergilenip açık artırmayla satıldı; Tom ve sınıf arkadaşları deniz fenerinin elle boyanmış kartpostallarını satarak şaşırtıcı bir miktar topladı."],["At the launch of the public appeal, Deniz was persuaded – against every instinct she had – to say a few words. She had prepared a careful speech, but when she looked out at the crowd she folded it up and spoke instead from the heart.","Halka açık bağış kampanyasının açılışında Deniz, tüm içgüdülerine rağmen birkaç söz söylemeye ikna edildi. Özenle hazırlanmış bir konuşması vardı ama kalabalığa baktığında onu katladı ve onun yerine içinden geldiği gibi konuştu."],["\"When I arrived here, I didn't know a single person, and my English was full of holes,\" she said. \"A lighthouse doesn't ask a ship where it comes from before it shows it the way home. This town did the same for me. I think that's worth keeping alight.\" The applause went on for a long time.","\"Buraya geldiğimde tek bir kişiyi tanımıyordum ve İngilizcem delik deşikti,\" dedi. \"Bir deniz feneri bir gemiye eve giden yolu göstermeden önce nereden geldiğini sormaz. Bu kasaba da benim için aynısını yaptı. Bence bu, yanık tutulmaya değer bir şey.\" Alkışlar uzun süre devam etti."]],"q":[["What made 'even the most ardent supporters wince'?",["the engineers' cost estimate","the bad weather","the company's threats"],0,"Mühendislerin maliyet tahmini."],["Why did Deniz fold up her speech?",["she had forgotten her glasses","she decided to speak spontaneously from the heart","the organisers told her to be brief"],1,"'spoke instead from the heart'"],["What comparison lies at the heart of her speech?",["the lighthouse and a school","a lighthouse guiding ships and the town welcoming her","the sea and her home city"],1,"Fener gemiye nereden geldiğini sormaz; kasaba da ona sormadı."]],"w":192},{"id":"C2-4","l":"C2","n":4,"t":"Relit","p":[["Eighteen months later, on the third of November – a date chosen with some deliberation – the people of Port Wren gathered once more on the headland. This time there were no candles. There was no need.","On sekiz ay sonra, 3 Kasım'da – özenle seçilmiş bir tarih – Port Wren halkı burunda bir kez daha toplandı. Bu sefer mum yoktu. Gerek de yoktu."],["William had come home for the occasion, frailer than before but insistent on climbing the restored staircase himself, one slow step at a time, with Mary a step behind him muttering that he would be the death of her yet.","William bu vesileyle eve dönmüştü; eskisinden daha zayıftı ama restore edilmiş merdiveni kendisi, ağır ağır, adım adım çıkmakta ısrar ediyordu; Mary de bir basamak arkasında, onun sonunda kendisini öldüreceğini homurdanıyordu."],["At exactly six o'clock, as dusk settled over the bay, William pressed the switch. For a heartbeat nothing happened. Then the great lens began to turn, and a beam of white light swept out across the water, over the harbour, over Gull Island, over the crowd that had fallen utterly silent.","Tam saat altıda, alacakaranlık koyun üzerine çökerken William düğmeye bastı. Bir kalp atışı süresince hiçbir şey olmadı. Sonra büyük mercek dönmeye başladı ve beyaz bir ışık huzmesi suyun üzerinden, limanın üzerinden, Martı Adası'nın üzerinden, tamamen susmuş kalabalığın üzerinden süpürüp geçti."],["Somewhere down by the harbour a ship's horn sounded, and then another, until every boat in Port Wren seemed to be answering. Sam, standing beside Deniz, made no attempt to hide his tears. \"Thirty years,\" he kept saying. \"Thirty years.\"","Limanın aşağılarında bir yerde bir gemi düdüğü öttü, ardından bir başkası; sanki Port Wren'deki her tekne karşılık veriyordu. Deniz'in yanında duran Sam gözyaşlarını saklamaya hiç çalışmadı. \"Otuz yıl,\" deyip duruyordu. \"Otuz yıl.\""]],"q":[["Why was the date 'chosen with some deliberation'?",["it was the anniversary of the storm","it was Deniz's birthday","the weather was best then"],0,"3 Kasım fırtına gecesinin yıldönümü."],["Why were there 'no candles' this time?",["they had been banned","the lighthouse itself would provide the light","it was too windy"],1,"Artık fenerin kendi ışığı vardı."],["What does 'he would be the death of her yet' suggest about Mary's attitude?",["affectionate exasperation","real anger","fear of heights"],0,"Sevgi dolu bir sitem."]],"w":168},{"id":"C2-5","l":"C2","n":5,"t":"Leaving Port Wren","p":[["Deniz's course came to an end the following spring. She had been offered a place at a university in the city, and although Port Wren was only two hours away by train, packing up her little room above the bakery felt like the end of something irretrievable.","Deniz'in kursu ertesi bahar sona erdi. Şehirdeki bir üniversitede kendisine yer teklif edilmişti ve Port Wren trenle sadece iki saat uzakta olsa da fırının üstündeki küçük odasını toplamak, geri getirilemez bir şeyin sonu gibi geliyordu."],["On her last evening she walked up to the headland alone. She thought about the girl who had stepped off the bus nearly two years earlier, exhausted and homesick, barely able to string a sentence together, and found that she hardly recognised her.","Son akşamında burna tek başına yürüdü. Neredeyse iki yıl önce otobüsten inen o kızı düşündü – bitkin, sıla hasreti çeken, iki cümleyi zar zor bir araya getirebilen – ve onu neredeyse tanıyamadığını fark etti."],["It wasn't merely that her English had improved, although it had, beyond anything she could have imagined. It was that she had learned something she suspected no textbook could teach: that a language is not a set of rules to be memorised but a door – and that what lies on the other side is people.","Mesele yalnızca İngilizcesinin gelişmiş olması değildi, gerçi hayal edebileceği her şeyin ötesinde gelişmişti. Mesele, hiçbir ders kitabının öğretemeyeceğinden şüphelendiği bir şeyi öğrenmiş olmasıydı: bir dilin ezberlenecek bir kurallar bütünü değil bir kapı olduğunu – ve öbür tarafta insanların bulunduğunu."],["Behind her, the lighthouse swept its beam across the darkening sea, steady and patient, as it would go on doing long after she had gone. Deniz took the old key from her pocket, the one Mary had insisted she keep, and smiled. Some doors, she thought, you never really close.","Arkasında deniz feneri, huzmesini kararan denizin üzerinde sabırla ve kararlılıkla gezdiriyordu; o gittikten çok sonra da böyle yapmaya devam edecekti. Deniz, Mary'nin saklaması için ısrar ettiği eski anahtarı cebinden çıkardı ve gülümsedi. Bazı kapılar, diye düşündü, hiçbir zaman gerçekten kapanmaz."]],"q":[["Why did packing up feel 'like the end of something irretrievable'?",["she was moving very far away","a unique period of her life was ending for good","she had lost her belongings"],1,"Şehir yakın ama o dönem bir daha geri gelmeyecek."],["According to Deniz, what is a language?",["a set of rules to memorise","a door that leads to people","a subject for exams"],1,"'not a set of rules... but a door'"],["What does the final line 'Some doors you never really close' imply?",["her connection to Port Wren will endure","she lost the key","she plans to return to Turkey"],0,"Port Wren'le bağı hiç kopmayacak."]],"w":196}];

// ---------- Oyunlaştırma ----------
const GMD=()=>{const g=S.gm||(S.gm={});g.d=g.d||{};g.ev=g.ev||{};g.tot=g.tot||{};g.bd=g.bd||{};g.goal=g.goal||50;g.combo=g.combo||0;g.best=g.best||0;g.gd=g.gd||{};g.q=g.q||{};return g};
const gmDay=(t)=>{const d=t?new Date(t):new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const gmToday=()=>GMD().d[gmDay()]||0;
const GMLV=n=>60*n*(n-1);
function gmLevel(xp){let n=1;while(GMLV(n+1)<=xp)n++;return n}
const GMRANK=[[1,'Çaylak','🐣'],[3,'Yolcu','🎒'],[6,'Gezgin','🧭'],[10,'Kâşif','🗺️'],[15,'Kaptan','⚓'],[20,'Bilge','🌟']];
const gmRank=n=>{let r=GMRANK[0];GMRANK.forEach(x=>{if(n>=x[0])r=x});return r};
// ----- bildirim, konfeti -----
let GMTQ=[],GMTB=false;
function gmToast(html,cls){GMTQ.push([html,cls||'']);if(!GMTB)gmToastNext()}
function gmToastNext(){const n=GMTQ.shift();if(!n){GMTB=false;return}GMTB=true;let el=document.getElementById('gmt');if(!el){el=document.createElement('div');el.id='gmt';document.body.appendChild(el)}
 el.className='gmt '+n[1];el.innerHTML=n[0];requestAnimationFrame(()=>el.classList.add('on'));setTimeout(()=>{el.classList.remove('on');setTimeout(gmToastNext,350)},2300)}
function gmConfetti(){try{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return}catch(e){}const c=document.createElement('canvas');c.className='gmc';document.body.appendChild(c);const x=c.getContext('2d'),W=c.width=innerWidth,H=c.height=innerHeight;
 const cs=['#2f5bff','#16a34a','#f59e0b','#ef4444','#a855f7','#06b6d4'],P=Array.from({length:110},()=>({x:W/2+(Math.random()-.5)*W*.3,y:H*.35,vx:(Math.random()-.5)*9,vy:-Math.random()*9-4,s:4+Math.random()*5,c:cs[Math.random()*cs.length|0],r:Math.random()*6,vr:(Math.random()-.5)*.3}));let t=0;
 const f=()=>{x.clearRect(0,0,W,H);P.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.vy+=.25;p.vx*=.99;p.r+=p.vr;x.save();x.translate(p.x,p.y);x.rotate(p.r);x.fillStyle=p.c;x.fillRect(-p.s/2,-p.s/2,p.s,p.s*.6);x.restore()});if(++t<110)requestAnimationFrame(f);else c.remove()};f()}
