let GMSKIP=false;
function gmXP(n){if(!n)return;const g=GMD(),k=gmDay(),before=g.d[k]||0;S.xp=(S.xp||0)+n;g.d[k]=before+n;
 const lv0=gmLevel(S.xp-n),lv1=gmLevel(S.xp);
 const t=new Date().toDateString();if(S.last!==t){const y=new Date(Date.now()-864e5).toDateString();S.streak=S.last===y?(S.streak||0)+1:1;S.last=t}
 if(before<g.goal&&g.d[k]>=g.goal){g.gd[k]=1;setTimeout(()=>{gmToast(`${MAVI}<b>Günlük hedef tamam!</b><span>${g.goal} XP · seri ${S.streak} gün</span>`,'goal');gmConfetti()},400)}
 if(lv1>lv0){const r=gmRank(lv1);setTimeout(()=>gmToast(`<b>${r[2]} Lv ${lv1}!</b><span>${r[1]} rütbesindesin</span>`,'lvl'),800)}
 save();gmBadges();gmQuests();try{hud()}catch(e){}}
function gmAns(ok){if(GMSKIP||cur==='plc')return;const g=GMD();if(ok){g.combo++;if(g.combo>g.best)g.best=g.combo;const b=g.combo>=10?5:g.combo>=5?3:0;gmXP(10+b);
  if([3,5,10,15,20,30,50].includes(g.combo))gmToast(`<b>🔥 ${g.combo}'li seri!</b><span>${g.combo>=5?'Her doğru cevap +'+(10+(g.combo>=10?5:3))+' XP':'Böyle devam'}</span>`,'combo')}
 else{g.combo=0;save()}}
