function gmQList(){const g=GMD(),k=gmDay();if(g.q.k===k&&g.q.l)return g.q.l;let seed=0;for(const c of k)seed=(seed*31+c.charCodeAt(0))%9973;
 const pool=[['gr',1,'1 dilbilgisi ünitesini bitir'],['ls',1,'1 dinleme metni çöz'],['id',1,'Bir deyim dersini tamamla'],['kel',1,'Günlük kelime dersini bitir'],['ok',1,'Bir okuma parçası ya da hikâye bitir'],['et',2,'Haritada 2 etap geç'],['combo',8,'8\'li doğru serisi yap']];
 const i1=seed%pool.length,i2=(i1+1+seed%(pool.length-1))%pool.length,a=[pool[i1],pool[i2===i1?(i1+1)%pool.length:i2]];
 g.q={k,l:[['xp',g.goal,'Günlük hedefine ulaş'],...a].map(x=>({t:x[0],n:x[1],d:x[2],ok:0}))};save();return g.q.l}
function gmQVal(t){const g=GMD(),e=g.ev[gmDay()]||{};if(t==='xp')return gmToday();if(t==='ok')return (e.oa||0)+(e.st||0)+(e.ids||0)+(e.ep||0);if(t==='combo')return g.qc||0;if(t==='et')return (e.et||0)+(e.boss||0);return e[t]||0}
