 const ws=shuf(words.filter(w=>w.l===x.L)),ii=shuf(IDD.map((r,i)=>i).filter(i=>IDD[i][1]===x.L));const nv=x.t==='et'?2:3;
 for(let k=0;k<nv;k++){if(k%2===0&&ws.length){const w=ws.shift(),ds=shuf(words.filter(y=>y.tr!==w.tr&&y.p===w.p)).slice(0,3).map(y=>y.tr),o=shuf([w.tr,...ds]);qs.push(['',['mc',`“${w.w}” ne demek?`,o,o.indexOf(w.tr),`${w.w}: ${w.tr}`]])}else if(ii.length){const i=ii.shift();qs.push(['',iMC(i,`“${IDD[i][0]}” ne anlama gelir?`,5)])}}
