// ---------- Kelime gücü (v2) ----------
const WST=['Yeni','Öğreniliyor','Pekişiyor','Öğrenildi','Kalıcı'],WSC=['#cbd5e1','#f59e0b','#3b82f6','#16a34a','#7c3aed'];
const WSD=['Henüz çalışılmadı','İlk günler: 10 dakika ve 1 gün sonra tekrar','1 gün sonra hatırladın, 3 gün sonra tekrar gelecek','3 gün ve 1 hafta sonra hatırladın','3 hafta sonra bile hatırladın'];
function wst(w){const s=S.sr[key(w)];if(!s)return 0;if(!s.b)return (s.w||s.r)?1:0;return s.b<=2?1:s.b===3?2:s.b<=5?3:4}
const isNewW=w=>{const s=S.sr[key(w)];return !s||(!s.b&&!s.w&&!s.r)};
const inList=w=>{const s=S.sr[key(w)];return !!s&&!!s.q&&isNewW(w)};
function wMark(w,known){const k=key(w),s=S.sr[k];if(known){S.sr[k]={b:5,due:Date.now()+IV[5],w:s?s.w||0:0,r:(s?s.r||0:0)+1,k:1}}else if(!s)S.sr[k]={b:0,due:0,w:0,q:1};else if(isNewW(w))s.q=1;save()}
function wCounts(a){const c=[0,0,0,0,0];let q=0;a.forEach(w=>{const x=wst(w);c[x]++;if(!x&&inList(w))q++});return [c,q]}
function wStack(c,h){const n=c.reduce((a,b)=>a+b,0)||1;return `<div class="wstk" style="height:${h||12}px">${c.map((v,i)=>v?`<i style="width:${v/n*100}%;background:${WSC[i]}"></i>`:'').join('')}</div>`}
function wDots(w){const s=S.sr[key(w)],b=s?s.b||0:0;return `<span class="wdots" title="Güç ${b}/6">${[1,2,3,4,5,6].map(i=>`<i class="${b>=i?'on':''}" style="${b>=i?'background:'+WSC[wst(w)]:''}"></i>`).join('')}</span>`}
function wNext(w){const s=S.sr[key(w)];if(!s||isNewW(w))return inList(w)?'listende':'';const d=s.due-Date.now();return d<=0?'tekrar zamanı':d<36e5?Math.ceil(d/6e4)+' dk':d<864e5?Math.round(d/36e5)+' sa':Math.round(d/864e5)+' gün'}
const wHard=()=>words.filter(w=>{if(!inA(w))return false;const s=S.sr[key(w)];return s&&(s.w||0)>=2&&wst(w)<3}).sort((a,b)=>S.sr[key(b)].w-S.sr[key(a)].w);
function wHomeLine(){const a=words.filter(inA),[c]=wCounts(a);return `<button class="lnk wln" onclick="go('kelimeler')">📊 ${AREA()?ARN[AREA()]+': ':''}${c[3]+c[4]} öğrenildi · ${c[1]+c[2]} öğreniliyor · ${a.length} ${AREA()?'fiillik':'kelimelik'} havuz ›</button>`}
function wHardLesson(){const ws=wHard().slice(0,10);if(!ws.length)return;const st=[];ws.forEach(w=>st.push({k:'quiz',w,rev:false}));shuf(ws).forEach(w=>st.push(w.f?{k:'form',w}:{k:'type',w,rev:true}));
 LS={st,i:0,ok:0,n:0,t0:Date.now(),nw:0,xp:S.xp,res:null,seen:[]};go('lesson')}
function wStudyLv(L){if(typeof lvSet==='function'&&S.lvl!==L&&!S.lvl)lvSet(L);S.f.l=L;S.f.t='';LS=null;save();DOPEN=false;go('lesson')}
function iKnow(w){wMark(w,true);LS.st=LS.st.filter((s,j)=>j<=LS.i||s.w!==w);S.nd.n=Math.max(0,S.nd.n-1);LS.nw=Math.max(0,LS.nw-1);
 let f=filt();if(!f.length)f=words;const r=f.filter(x=>isNewW(x)&&!LS.st.some(s=>s.w===x)).map((x,i)=>[x,i]).sort((a,b)=>(inList(b[0])-inList(a[0]))||((LO[a[0].l]||2)-(LO[b[0].l]||2))||a[1]-b[1])[0];
 if(r){const x=r[0];LS.st.push({k:'intro',w:x},{k:'quiz',w:x,rev:false},x.f?{k:'form',w:x}:{k:'type',w:x,rev:true})}
 gmToast(`<b>✓ ${esc(fj(w))}: öğrenildi</b><span>${r?'Yerine yeni bir kelime eklendi. ':''}3 hafta sonra bir kez kontrol edilecek</span>`,'goal');LS.res=null;lsNext()}
let KWT=null;
function kelimeler(){$('#cnt').textContent='';KWT=KWT||{st:1,q:'',n:50};const words=AW(),A=AREA(),U=A==='yds'?'kelime':A?'fiil':'kelime';const [c,q]=wCounts(words),M=$('#main'),lv=LVL.filter(L=>words.some(w=>w.l===L)),hard=wHard();
 const e0=new Date();e0.setHours(24,0,0,0);const E=i=>e0.getTime()+i*864e5;
 const fc=[...Array(7)].map((_,i)=>[i===0?'Bugün':i===1?'Yarın':new Date(E(i)-1).toLocaleDateString('tr-TR',{weekday:'short'}),words.filter(w=>{const s=S.sr[key(w)];if(!s||isNewW(w))return false;return s.due<=E(i)&&(i===0||s.due>E(i-1))}).length]),fm2=Math.max(5,...fc.map(x=>x[1]));
 const tabs=[[1,'Öğreniliyor'],[2,'Pekişiyor'],[3,'Öğrenildi'],[4,'Kalıcı'],['q','Listende'],['h','Zor'],['all','Tümü']];
 const tps=[...new Set(words.map(w=>w.t))].map(t=>[t,words.filter(w=>w.t===t)]).sort((a,b)=>b[1].length-a[1].length);
 M.innerHTML=`<div class="seg ark">${Object.keys(ARN).map(k=>`<button data-ak="${k}" class="${A===k?'on':''}">${ARN[k]}</button>`).join('')}</div><div class="card left"><div class="gbar"><p class="big sm" style="margin:0">${A?ARN[A]:'Kelimelerim'}</p><span class="ex">${words.length} ${U} · ${lv[0]}–${lv[lv.length-1]}</span></div>${A?`<p class="ex" style="margin:0 0 8px">${ADS[A]}</p>`:''}
 ${wStack(c,16)}<div class="wleg">${c.map((v,i)=>`<span><i style="background:${WSC[i]}"></i>${WST[i]} <b>${v}</b></span>`).join('')}</div>
 ${q?`<p class="ex" style="margin:6px 0 0">📌 Öğrenme listende bekleyen ${q} ${U} var; sıradaki derslerde önce bunlar gelir.</p>`:''}
 <details class="wexp"><summary class="ex">Kelime gücü nasıl ilerler?</summary>${WST.map((t,i)=>`<p class="ex"><i class="wsw" style="background:${WSC[i]}"></i><b>${t}:</b> ${WSD[i]}</p>`).join('')}<p class="ex">Her kelimenin 6 güç basamağı var. Tekrar zamanı gelince doğru bilirsen bir basamak çıkar, aralık uzar (10 dk, 1, 3, 7, 21, 60 gün). Yanlış yaparsan iki basamak geriler ve kısa süre sonra yeniden sorulur. Zamanı gelmeden yaptığın ek pratik gücü değiştirmez ama hatırlamana yardım eder.</p></details>
 <div class="wbtn"><button class="btn" onclick="DOPEN=false;go('lesson')">Günlük derse başla</button><button class="btn no" id="wayk">🧹 Bildiklerini ayıkla</button>${hard.length?`<button class="btn no" onclick="wHardLesson()">🔥 Zorlandıklarını çalış (${Math.min(10,hard.length)})</button>`:''}</div></div>
 <div class="card left"><b>Tekrar takvimi</b><div class="wfc">${fc.map(([d,n])=>`<div><span class="wfn">${n}</span><i style="height:${Math.round(n/fm2*60)+2}px"></i><small>${d}</small></div>`).join('')}</div><p class="ex" style="margin:4px 0 0">Günlük ders, tekrar zamanı gelen kelimeleri en eskiden başlayarak getirir.</p></div>
 ${A?`<div class="card left"><b>${A==='iv'?'Kalıplara göre':A==='yds'?'Türe göre':'Parçacığa göre'}</b><p class="ex" style="margin:2px 0 6px">${A==='iv'?'Aynı kalıptaki fiilleri birlikte çalışmak akılda tutmayı kolaylaştırır.':A==='yds'?'Fiiller, sıfatlar, isimler, zarflar, phrasal verbs, bağlaçlar ve kalıplar ayrı ayrı çalışılabilir.':'Aynı parçacık çoğu zaman benzer bir anlam katar: up tamamlama/artış, out dışarı/sonuna kadar, off ayrılma/kesilme, down azalma.'}</p>${tps.map(([t,a])=>{const [cc]=wCounts(a);return `<div class="wlv"><div class="gbar"><span><b>${esc(t)}</b></span><span class="ex">${cc[3]+cc[4]} / ${a.length} öğrenildi</span></div>${wStack(cc,8)}<div class="wlvb"><button class="lnk" data-wtp="${esc(t)}">Bu grubu çalış</button></div></div>`}).join('')}</div>`:''}<div class="card left"><b>Seviyelere göre</b>${lv.map(L=>{const a=words.filter(w=>w.l===L),[cc]=wCounts(a);return `<div class="wlv"><div class="gbar"><span><b>${L}</b> <span class="ex">${LVN[L]||''}</span></span><span class="ex">${cc[3]+cc[4]} / ${a.length} öğrenildi</span></div>${wStack(cc,10)}${A?'':`<p class="ex" style="margin:4px 0 0">📖 ${rdCov(a)} / ${a.length} kelime okuma metinlerinde geçiyor</p>`}<div class="wlvb"><button class="lnk" data-wst="${L}">Bu seviyeyi çalış</button>${cc[0]?`<button class="lnk" data-way="${L}">Bildiklerini ayıkla</button>`:''}</div></div>`}).join('')}</div>
 <div class="card left"><div class="seg wtab">${tabs.map(([k,t])=>`<button data-wt="${k}" class="${String(KWT.st)===String(k)?'on':''}">${t}</button>`).join('')}</div><input class="inp" id="wq" placeholder="Kelime ya da anlam ara" value="${esc(KWT.q)}" style="margin:8px 0"><div id="wls"></div></div>`;
 const list=()=>{const t=KWT.st,qq=nz(KWT.q||'');let a=t==='all'?words:t==='q'?words.filter(inList):t==='h'?hard:words.filter(w=>wst(w)===+t);
  if(qq)a=a.filter(w=>nz(fj(w)).includes(qq)||nz(w.tr).includes(qq));
  if(t!=='all'&&t!=='q'&&t!=='h')a=a.slice().sort((x,y)=>S.sr[key(x)].due-S.sr[key(y)].due);
  $('#wls').innerHTML=`<p class="ex" style="margin:0 0 6px">${a.length} ${U}</p>`+(a.length?a.slice(0,KWT.n).map(w=>`<button class="wrow" data-wk="${esc(key(w))}"><span class="wrw"><b>${esc(fj(w))}</b> <small class="ex">${esc(w.tr)}</small></span><span class="wrm"><span class="wlb">${w.l}</span>${wDots(w)}<small class="ex">${wNext(w)}</small></span></button>`).join('')+(a.length>KWT.n?`<button class="lnk" id="wmore">${a.length-KWT.n} kelime daha göster</button>`:''):'<p class="ex">Bu grupta ${U} yok.</p>');
  document.querySelectorAll('[data-wk]').forEach(b=>b.onclick=()=>{const w=words.find(x=>key(x)===b.dataset.wk);if(w)wPop(w)});const m=$('#wmore');if(m)m.onclick=()=>{KWT.n+=100;list()}};
 list();
 document.querySelectorAll('[data-wt]').forEach(b=>b.onclick=()=>{KWT.st=b.dataset.wt;KWT.n=50;document.querySelectorAll('[data-wt]').forEach(x=>x.classList.toggle('on',x===b));list()});
 let tm;$('#wq').oninput=e=>{clearTimeout(tm);tm=setTimeout(()=>{KWT.q=e.target.value;KWT.n=50;list()},200)};
 document.querySelectorAll('[data-wst]').forEach(b=>b.onclick=()=>wStudyLv(b.dataset.wst));
 document.querySelectorAll('[data-way]').forEach(b=>b.onclick=()=>ayStart(b.dataset.way));
 $('#wayk').onclick=()=>ayPick();
 document.querySelectorAll('[data-ak]').forEach(b=>b.onclick=()=>{aSet(b.dataset.ak);KWT.n=50;kelimeler()});
 document.querySelectorAll('[data-wtp]').forEach(b=>b.onclick=()=>{S.f.t=b.dataset.wtp;S.f.l='';LS=null;save();DOPEN=false;go('lesson')})}
function wPop(w){const s=S.sr[key(w)],x=wst(w);const [o,cl]=yolSheet(`${bd(w)}<div style="height:10px"></div>${full(w)}<p class="ex" style="margin:8px 0 0">Durum: <b style="color:${WSC[x]}">${WST[x]}</b> ${wDots(w)} ${s&&!isNewW(w)?'· sonraki tekrar: '+wNext(w)+(s.w?` · ${s.w} kez yanlış`:''):''}</p>
 ${isNewW(w)?(inList(w)?`<button class="btn no" data-wa="rm">Listeden çıkar</button>`:`<button class="btn" data-wa="q">📌 Öğrenme listeme ekle</button>`):''}${x<3?`<button class="btn no" data-wa="k">✓ Bunu zaten biliyorum</button>`:''}${!isNewW(w)?`<button class="btn no" data-wa="r">↺ Sıfırla, yeniden öğreneceğim</button>`:''}`);
 o.querySelectorAll('[data-wa]').forEach(b=>b.onclick=()=>{const a=b.dataset.wa,k=key(w);if(a==='q')wMark(w,false);else if(a==='k')wMark(w,true);else if(a==='rm')delete S.sr[k];else if(a==='r')S.sr[k]={b:0,due:0,w:0,q:1};save();cl();if(cur==='kelimeler')kelimeler()})}
function ayPick(){const words=AW();const lv=LVL.filter(L=>words.some(w=>w.l===L&&isNewW(w)&&!inList(w)));const [o,cl]=yolSheet(`<p class="big sm" style="margin:0 0 6px">Bildiklerini ayıkla</p><p class="ex">Bir seviyeden 15 yeni kelime gelir. Anlamını doğru seçtiklerin <b>öğrenildi</b> sayılır, bilmediklerin öğrenme listene eklenir. Böylece derslerde bildiğin kelimelerle vakit kaybetmezsin.</p><div class="opts">${lv.map(L=>`<button class="opt" data-ap="${L}"><b>${L}</b> <small class="ex">${LVN[L]||''} · ${words.filter(w=>w.l===L&&isNewW(w)&&!inList(w)).length} yeni kelime</small></button>`).join('')}</div>`);
 o.querySelectorAll('[data-ap]').forEach(b=>b.onclick=()=>{cl();ayStart(b.dataset.ap)})}
let AY=null;
function ayStart(L){const words=AW();const pool=shuf(words.filter(w=>w.l===L&&isNewW(w)&&!inList(w)));if(!pool.length){gmToast(`<b>${L}: ayıklanacak yeni kelime kalmadı</b><span>Hepsi çalışılmış ya da listende</span>`,'lk');return}
 AY={L,ws:pool.slice(0,15),k:0,kn:[],un:[],pool:pool.length,a:null,U:AREA()?'fiili':'kelimeyi'};go('ayikla')}
function ayikla(){$('#cnt').textContent='';if(!AY){go('kelimeler');return}const M=$('#main'),n=AY.ws.length;
 if(AY.k>=n){const kn=AY.kn.length,est=Math.round(kn/n*AY.pool);if(!AY.gmd){AY.gmd=1;gmDone('ay',Math.round(kn/n*100))}
  M.innerHTML=`<div class="card left"><p class="ex" style="margin:0">${AY.L} · Bildiklerini ayıkla</p><p class="big">${kn} / ${n}</p><p class="se">${kn?`<b>${kn}</b> ${AY.U} zaten biliyorsun; bunlar <b>öğrenildi</b> sayıldı ve 3 hafta sonra bir kez kontrol için tekrar gelecek.`:'Bu turda bildiğin kelime çıkmadı.'} ${AY.un.length?`<b>${AY.un.length}</b> ${AY.U} öğrenme listene eklendi; sıradaki derslerde önce bunlar gelecek.`:''}</p>
  ${AY.pool>n?`<p class="ex">Bu orana göre ${AY.L} seviyesindeki ${AY.pool} yeni kelimenin yaklaşık <b>${est}</b> tanesini biliyor olabilirsin.${kn/n>=.7?' Birkaç tur daha ayıklamak işine yarar.':kn/n<=.3?' Bu seviyede öğreneceğin çok kelime var; derslerle ilerlemek daha verimli.':''}</p>`:''}
  ${AY.un.length?`<div class="wun">${AY.un.map(w=>`<span><b>${esc(fj(w))}</b> ${esc(w.tr)}</span>`).join('')}</div>`:''}
  ${AY.pool>n?`<button class="btn" id="aym">15 kelime daha</button>`:''}<button class="btn ${AY.pool>n?'no':''}" id="ayl">Listemdeki kelimelerle derse başla</button><button class="lnk" id="ayk">Kelimelerim</button></div>`;
  const m=$('#aym');if(m)m.onclick=()=>ayStart(AY.L);$('#ayl').onclick=()=>wStudyLv(AY.L);$('#ayk').onclick=()=>{AY=null;go('kelimeler')};return}
 const w=AY.ws[AY.k];if(!AY.o||AY.o.w!==w)AY.o={w,o:shuf([w,...(w.f?ivFake(w):distract(w,3))])};const o=AY.o.o,lab=x=>w.f?(x===w?w.f.map(f=>f.split('/')[0]).join(' – '):x.fk):x.tr;
 M.innerHTML=`<div class="gbar"><button class="lnk" id="ayb">‹ Kelimelerim</button><span class="ex">${AY.L} · Bildiklerini ayıkla · ${AY.k+1}/${n}</span></div><div class="ybar" style="--rc:#16a34a"><i style="width:${AY.k/n*100}%"></i></div>
 <div class="card"><span class="lv">${w.l}</span><div class="big">${esc(w.w)} ${SP(w.w)}</div><div class="pos">${esc(AB[w.p]||w.p)}${w.f?' · '+esc(w.tr):''}</div><p class="ex">${w.f?'V2 (past) ve V3 (past participle) hâlleri hangisi?':'Anlamını biliyor musun?'} Emin değilsen “Bilmiyorum”a bas; tahmin etmek seni yavaşlatır.</p></div>
 <div class="opts">${o.map((x,i)=>`<button class="opt" data-ay="${i}">${esc(lab(x))}</button>`).join('')}<button class="opt ayno" data-ay="-1">🤷 Bilmiyorum</button></div><div id="ayf"></div>`;
 $('#ayb').onclick=()=>{AY=null;go('kelimeler')};
 const bs=document.querySelectorAll('[data-ay]');bs.forEach(b=>b.onclick=()=>{const i=+b.dataset.ay,ok=i>=0&&o[i]===w;bs.forEach(x=>{x.disabled=true;if(+x.dataset.ay>=0&&o[+x.dataset.ay]===w)x.classList.add('good')});if(!ok&&i>=0)b.classList.add('bad');
  if(ok){wMark(w,true);AY.kn.push(w);gmAns(true);setTimeout(()=>{if(AY&&AY.ws[AY.k]===w){AY.k++;ayikla()}},650)}
  else{wMark(w,false);AY.un.push(w);$('#ayf').innerHTML=`<div class="card left rv">${full(w)}</div><button class="btn" id="ayn">Devam ›</button>`;$('#ayn').onclick=()=>{AY.k++;ayikla()};try{$('#ayn').scrollIntoView({block:'nearest'})}catch(e){}}})}

// ---------- Alanlar: kelimeler, phrasal verbs, düzensiz fiiller ----------
const ADS={pv:'Fiil + parçacık (up, out, off…) birleşince çoğu zaman yeni bir anlam çıkar. Burada her birini anlamı ve örnek cümlesiyle, kelimelerle aynı tekrar düzeninde öğrenirsin.',iv:'Düzensiz fiillerin geçmiş (V2) ve üçüncü (V3) hâlleri ezberlenmelidir. Derslerde anlamın yanında V2 ve V3 hâllerini yazarak çalışırsın.'};
const AW=()=>words.filter(inA);
function aSet(k){S.f=S.f||{};const o=S.f.k||'';if(o===k)return;S.nda=S.nda||{};S.nda[o]=S.nd;S.nd=S.nda[k]||null;S.f.k=k;S.f.t='';if(S.f.l&&!words.some(w=>inA(w)&&w.l===S.f.l))S.f.l='';S.ci=0;S.mp=0;LS=null;RQ=[];save()}
const fj=w=>w.f?[w.w,...w.f.map(f=>f.split('/')[0])].join(' – '):w.w;
const ivF=w=>`<div class="ivf">${['V1 · base','V2 · past','V3 · participle'].map((h,i)=>{const v=i?w.f[i-1]:w.w;return `<div><small>${h}</small><b>${esc(v.replace(/\//g,' / '))}</b>${SP(v.split('/')[0])}</div>`}).join('')}</div>`;
function ivReg(b){return /e$/.test(b)?b+'d':/[^aeiou]y$/.test(b)?b.slice(0,-1)+'ied':b+'ed'}
function ivFake(w){const b=w.w,[v2,v3]=w.f.map(f=>f.split('/')[0]),r=ivReg(b),ok=v2+' – '+v3,c=[r+' – '+r,v2+' – '+v2,v3+' – '+v3,v3+' – '+v2,v2+' – '+r,r+' – '+v3,b+' – '+v2,b+' – '+v3,b+' – '+b];
 const o=[...new Set(c)].filter(x=>x!==ok&&x!==w.f.join(' – '));return shuf(o).slice(0,3).map(fk=>({fk}))}
function ivForm(w){const sol=w.f.map(f=>f.split('/').map(nz));
 $('#main').innerHTML=`<div class="card">${bd(w)}<div class="big">${esc(w.w)} ${SP(w.w)}</div><div class="pos">${esc(w.tr)}</div><p class="ex">V2 (past simple) ve V3 (past participle) hâllerini yaz.</p></div>
 <label class="ex">V2 · past</label><input id="iv2" class="inp" autocomplete="off" autocapitalize="none" autocorrect="off" spellcheck="false" placeholder="ör. went"><label class="ex" style="display:block;margin-top:8px">V3 · past participle</label><input id="iv3" class="inp" autocomplete="off" autocapitalize="none" autocorrect="off" spellcheck="false" placeholder="ör. gone">
 <button class="btn" id="chk" style="margin-top:10px">Kontrol et</button><button class="btn no" id="sa" style="margin-top:8px">Cevabı göster</button><div id="fb"></div>${navRow()}`;
 const i2=$('#iv2'),i3=$('#iv3');i2.focus();let done=false;
 const fin=(ok,r)=>{done=true;[i2,i3].forEach((x,j)=>{x.disabled=true;if(r)x.classList.add(r[j]?'ok':'bad')});$('#chk').hidden=true;$('#sa').hidden=true;award(w,ok);setTimeout(()=>say(w.w+', '+w.f.map(f=>f.split('/')[0]).join(', ')),150);
  $('#fb').innerHTML=`<p class="vd ${ok?'good':'bad'}">${ok?'Doğru!':r?'Tam değil. Doğrusu:':'Doğrusu:'} <b>${esc(fj(w))}</b></p>${w.f.some(f=>f.includes('/'))?`<p class="ex">Kabul edilen biçimler: ${esc(w.f.join(' · '))}</p>`:''}${rv(w)}`};
 const check=()=>{if(done)return;const a=[nz(i2.value),nz(i3.value)];if(!a[0]||!a[1]){(a[0]?i3:i2).focus();return}const r=a.map((v,j)=>sol[j].includes(v));fin(r[0]&&r[1],r)};
 $('#chk').onclick=check;i2.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();i3.focus()}};i3.onkeydown=e=>{if(e.key==='Enter')check()};$('#sa').onclick=()=>{if(!done)fin(false,null)};wire(null)}

// ---------- Yedekleme: hesap (bulut) + dosya ----------
const YD={db:null,uid:null,meta:null,st:'init',busy:false,last:0,asked:false};
const YDK=['kv1','kvx'],YDC=90000;
function ydDev(){try{let d=localStorage.getItem('kvdev');if(!d){d=Math.random().toString(36).slice(2,10);localStorage.setItem('kvdev',d)}return d}catch(e){return 'x'}}
function ydSum(){let r=0;Object.values(S.sr||{}).forEach(x=>r+=(x.r||0));return {xp:S.xp||0,rv:r,lw:words.filter(learned).length}}
function ydPack(){const ls={};YDK.forEach(k=>{try{const v=localStorage.getItem(k);if(v!=null)ls[k]=v}catch(e){}});return {app:'kelime-atolyesi',v:1,at:new Date().toISOString(),dev:ydDev(),sum:ydSum(),ls}}
const ydAgo=t=>{const d=(Date.now()-new Date(t).getTime())/1e3;return d<90?'az önce':d<3600?Math.round(d/60)+' dk önce':d<86400?Math.round(d/3600)+' sa önce':Math.round(d/86400)+' gün önce'};
const ydDate=t=>new Date(t).toLocaleString('tr-TR',{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'});
function ydApply(p){if(!p||p.app!=='kelime-atolyesi'||!p.ls||!p.ls.kv1)throw new Error('bad');JSON.parse(p.ls.kv1);
 try{const cur=localStorage.getItem('kv1');if(cur)localStorage.setItem('kv1_prev',cur)}catch(e){}
 YDK.forEach(k=>{try{if(p.ls[k]!=null)localStorage.setItem(k,p.ls[k]);else localStorage.removeItem(k)}catch(e){}});
 try{sessionStorage.setItem('kvrest','1')}catch(e){}location.reload()}
// --- bulut ---
async function ydInit(){try{if(!window.claude||!claude.use){YD.st='off';return}
 const [db,us]=await Promise.all([claude.use('db'),claude.use('user')]);if(!db||!us){YD.st='off';ydRef();return}
 const uid=await us.id();if(!uid){YD.st='off';ydRef();return}YD.db=db;YD.uid=uid;
 const m=await db.doc('data/users/'+uid+'/bkm').get();YD.meta=m.exists?m.data():null;YD.st='on';
 try{if(sessionStorage.getItem('kvrest')){sessionStorage.removeItem('kvrest');gmToast('<b>✓ İlerleme geri yüklendi</b><span>Kaldığın yerden devam edebilirsin</span>','goal');YD.last=Date.now();ydRef();return}}catch(e){}
 const me=ydSum(),cm=YD.meta;
 if(cm&&cm.dev!==ydDev()&&((cm.sum||{}).xp||0)>me.xp){ydOffer();ydRef();return}
 if(!cm||Date.now()-new Date(cm.at).getTime()>6*36e5)ydCloudSave(true);ydRef()}catch(e){YD.st='off';ydRef()}}
async function ydCloudSave(auto){if(!YD.db||YD.busy)return false;const cm=YD.meta,me=ydSum();
 if(auto&&cm&&cm.dev!==ydDev()&&((cm.sum||{}).xp||0)>me.xp)return false;
 if(auto&&cm&&cm.dev===ydDev()&&(cm.sum||{}).xp===me.xp&&(cm.sum||{}).rv===me.rv)return false;
 YD.busy=true;try{const p=ydPack(),s=JSON.stringify(p.ls),n=Math.ceil(s.length/YDC),base='data/users/'+YD.uid+'/';
  for(let i=0;i<n;i++)await YD.db.doc(base+'bk'+i).set({i,d:s.slice(i*YDC,(i+1)*YDC)});
  const meta={at:p.at,dev:p.dev,sum:p.sum,n,len:s.length};await YD.db.doc(base+'bkm').set(meta);YD.meta=meta;YD.last=Date.now();YD.busy=false;ydRef();return true}
 catch(e){YD.busy=false;if(e&&(e.code==='invalid_argument'||e.code==='not_granted'||e.code==='revoked'))YD.st='off';YD.err=e&&e.code;ydRef();return false}}
async function ydCloudLoad(){const m=YD.meta;if(!YD.db||!m)return;const base='data/users/'+YD.uid+'/';let s='';
 for(let i=0;i<m.n;i++){const d=await YD.db.doc(base+'bk'+i).get();if(!d.exists)throw new Error('eksik');s+=d.data().d}
 if(s.length!==m.len)throw new Error('eksik');ydApply({app:'kelime-atolyesi',ls:JSON.parse(s)})}
function ydOffer(){if(YD.asked)return;YD.asked=true;const c=YD.meta,s=c.sum||{};
 const [o,cl]=yolSheet(`<p class="big sm" style="margin:0 0 6px">☁️ Hesabında daha yeni bir ilerleme var</p><p class="se">Başka bir cihazda ${ydDate(c.at)} tarihinde kaydedilmiş: <b>${s.xp||0} XP</b>, <b>${s.lw||0}</b> öğrenilmiş kelime. Bu cihazda ${ydSum().xp} XP var.</p><p class="ex">Yüklersen bu cihazdaki ilerlemenin yerini alır (eskisi bir kez geri alınabilir şekilde saklanır).</p><button class="btn" data-yd="y">Bu cihaza yükle</button><button class="btn no" data-yd="n" style="margin-top:8px">Şimdilik değil</button>`);
 o.querySelector('[data-yd="y"]').onclick=async e=>{e.target.disabled=true;e.target.textContent='Yükleniyor...';try{await ydCloudLoad()}catch(er){e.target.textContent='Yüklenemedi, sonra tekrar dene'}};o.querySelector('[data-yd="n"]').onclick=cl}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&YD.st==='on'&&Date.now()-YD.last>15*6e4)ydCloudSave(true)});
// --- dosya ---
async function ydDownload(){const p=ydPack(),txt=JSON.stringify(p),fn='kelime-atolyesi-yedek-'+p.at.slice(0,10)+'.json';
 let dl=null;try{dl=window.claude&&claude.use?await claude.use('downloads'):null}catch(e){}
 if(dl){try{await dl.save({filename:fn,data:txt});S.ydf=p.at;save();ydRef();gmToast('<b>⬇️ Yedek dosyası kaydedildi</b><span>'+fn+'</span>','goal')}catch(e){if(e&&e.code!=='declined')gmToast('<b>Dosya kaydedilemedi</b><span>Hesap yedeği yine de çalışıyor</span>','lk')}return}
 try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([txt],{type:'application/json'}));a.download=fn;document.body.appendChild(a);a.click();a.remove();S.ydf=p.at;save();ydRef()}catch(e){gmToast('<b>Bu görünümde dosya indirilemiyor</b>','lk')}}
function ydUpload(f){const r=new FileReader();r.onload=()=>{let p;try{p=JSON.parse(r.result);if(!p||p.app!=='kelime-atolyesi'||!p.ls||!p.ls.kv1)throw 0;JSON.parse(p.ls.kv1)}catch(e){gmToast('<b>Bu dosya bir Kelime Atölyesi yedeği değil</b>','lk');return}
 const s=p.sum||{};const [o,cl]=yolSheet(`<p class="big sm" style="margin:0 0 6px">Yedeği geri yükle</p><p class="se">${ydDate(p.at)} tarihli yedek: <b>${s.xp||0} XP</b>, <b>${s.lw||0}</b> öğrenilmiş kelime.</p><p class="ex">Bu cihazdaki ilerlemenin yerini alır. Şu anki ilerlemen bir kez geri alınabilir şekilde saklanır.</p><button class="btn" data-yd="y">Geri yükle</button><button class="btn no" data-yd="n" style="margin-top:8px">Vazgeç</button>`);
 o.querySelector('[data-yd="y"]').onclick=()=>ydApply(p);o.querySelector('[data-yd="n"]').onclick=cl};r.readAsText(f)}
function ydUndo(){try{const v=localStorage.getItem('kv1_prev');if(!v)return;const cur=localStorage.getItem('kv1');localStorage.setItem('kv1',v);if(cur)localStorage.setItem('kv1_prev',cur);location.reload()}catch(e){}}
// --- kart ---
function ydHTML(){const m=YD.meta,on=YD.st==='on';let prev=false;try{prev=!!localStorage.getItem('kv1_prev')}catch(e){}
 return `<p class="big sm" style="margin:0 0 4px">Yedekleme</p>
 ${on?`<p class="se" style="margin:0">☁️ İlerlemen hesabına <b>otomatik yedekleniyor</b>.${m?` Son yedek: <b>${ydAgo(m.at)}</b>${m.dev!==ydDev()?' (başka bir cihazdan)':''}.`:''}</p><p class="ex">Başka bir cihazda ya da tarayıcıda bu sayfayı açtığında ilerlemeni oraya yüklemeyi önerir.</p>
 <div class="wbtn"><button class="btn no" data-yda="cs">☁️ Şimdi yedekle</button>${m&&m.dev!==ydDev()?`<button class="btn no" data-yda="cl">☁️ Hesabımdaki yedeği yükle</button>`:''}</div>`
 :YD.st==='init'?`<p class="ex">Hesap yedeği kontrol ediliyor…</p>`:`<p class="ex">Hesap yok: ilerlemen yalnızca bu tarayıcıda duruyor. Tarayıcı verisi silinirse kaybolur, ara sıra yedek dosyası indir; başka cihazda yedekten yükleyebilirsin.</p>`}
 <div class="wbtn"><button class="btn no" data-yda="fd">⬇️ Yedek dosyası indir</button><button class="btn no" data-yda="fu">⬆️ Yedek dosyasından yükle</button><input type="file" id="ydf" accept=".json,application/json" hidden></div>
 <p class="ex" style="margin:6px 0 0">${S.ydf?'Son dosya yedeği: '+ydAgo(S.ydf)+'. ':''}Eklediğin PDF kitaplar yedeğe dahil değil; bu cihazda kalır.${prev?' <button class="lnk" data-yda="un">Son geri yüklemeyi geri al</button>':''}</p>`}
function ydRef(){const c=document.getElementById('ydc');if(c){c.innerHTML=ydHTML();ydWire(c)}}
function ydWire(c){c.querySelectorAll('[data-yda]').forEach(b=>b.onclick=async()=>{const a=b.dataset.yda;
 if(a==='cs'){b.disabled=true;b.textContent='Yedekleniyor…';const ok=await ydCloudSave(false);if(ok)gmToast('<b>☁️ Hesabına yedeklendi</b>','goal');ydRef()}
 else if(a==='cl'){b.disabled=true;b.textContent='Yükleniyor…';try{await ydCloudLoad()}catch(e){b.textContent='Yüklenemedi'}}
 else if(a==='fd')ydDownload();else if(a==='fu')c.querySelector('#ydf').click();else if(a==='un')ydUndo()});
 const f=c.querySelector('#ydf');if(f)f.onchange=e=>{const x=e.target.files&&e.target.files[0];if(x)ydUpload(x);e.target.value=''}}
function backupCard(){$('#main').insertAdjacentHTML('beforeend','<div class="card left" id="ydc"></div>');ydRef()}
setTimeout(ydInit,1200);

