 if(u.rd.length)out.push({k:'rd',ic:'📖',t:'Okuma',core:1,need:Math.min(2,u.rd.length),items:u.rd.map(x=>{const l=unItemLabel('rd',x),k=String(l).indexOf(': ');return {lab:k>0?l.slice(k+2):l,sub:k>0?l.slice(0,k):'Okuma',m:7,done:unItemDone('rd',x),open:()=>unItemOpen('rd',x)}})});
 const tb=m3St('ut',u.id).best;out.push({k:'ut',ic:'🏁',t:'Ünite sonu testi',core:1,need:1,items:[{lab:'Ünite sonu testi',sub:tb!=null?`En iyi sonucun %${tb}${tb>=70?' ✓':' · geçmek için %70'}`:'20 soru · geçme notu %70',m:12,done:tb!=null&&tb>=70,open:()=>{UX={id:u.id,test:1};UTQ=null;go('unite')}}]});
 // ek çalışmalar
