function unProg(u){const st=unSteps(u),c=st.filter(s=>s.core);return [c.filter(s=>s.done).length,c.length,st]}
function unCur(L){L=L||S.lvl||'A1';const a=unByL(L);return a.find(u=>!unTestDone(u))||a[a.length-1]}
function unNext(u,nk){const st=unSteps(u);for(const s of st){if(!s.core||s.done||(nk&&s.k==='kel'))continue;const it=s.items.find(i=>!i.done);if(it)return {s,it}}return null}
function unDoneTotal(){let n=0;LSL.forEach(L=>{const u=unCur(L);if(u)n+=unProg(u)[0]});return n+UNITS.filter(unTestDone).length*20}
function unDayDelta(){const k=gmDay(),c=unDoneTotal();if(!S.ubase||S.ubase.d!==k){S.ubase={d:k,n:c};save()}return c-S.ubase.n}
