 const rv=rk=>{const us=unRvUnits(R,rk),on=us.every(unTestDone),dn=unRvDone(R,rk),b=m3St('ur',R+'-'+rk).best,x=OX[k++%8]*52;return `<div class="upn rv ${dn?'ok':''}" style="--x:${x}px"><button class="upb" data-unr="${rk}" ${on?'':'disabled'} aria-label="Karma tekrar"><span class="upr" style="--p:${dn?100:0}"><span class="upi">${dn?'✓':'🎁'}</span></span></button><div class="upt"><small>Karma tekrar</small><b>Ünite ${us[0].n}–${us[us.length-1].n}</b><small>${on?(b!=null?`en iyi %${b}`:'20 soru'):'3 ünite bitince açılır'}</small></div></div>`};
