const unRvId=(L,k)=>`R:${L}:${k}`;
function unRvUnits(L,k){return unByL(L).filter(u=>u.n>(k-1)*3&&u.n<=k*3)}
const unRvDone=(L,k)=>(m3St('ur',L+'-'+k).best||0)>=70;
function unRvPend(L){const a=unByL(L),K=Math.floor(a.length/3);for(let k=1;k<=K;k++){const us=unRvUnits(L,k);if(us.every(unTestDone)&&!unRvDone(L,k))return k}return 0}
