 const [d,n,st]=unProg(u),nx=unNext(u),ok=unTestDone(u),a=unByL(u.l),core=st.map((s,i)=>[s,i]).filter(x=>x[0].core),ext=st.map((s,i)=>[s,i]).filter(x=>!x[0].core),ed=ext.filter(x=>x[0].done).length,cd=unCD(u.id),cy=u.cd.filter((c,i)=>cd[i]===2).length,nu=a.find(x=>x.n===u.n+1);
