 const step=([s,si])=>`<details class="usd ${s.done?'ok':''}" ${nx&&nx.s.k===s.k?'open':''}><summary><span class="usi">${s.done?'✓':s.ic}</span><span class="ust">${esc(s.t)}</span><span class="ex">${s.done?'tamam':s.need<s.items.length?`${s.dn} / ${s.need}`:`${s.dn} / ${s.items.length}`}</span></summary>${s.items.map((it,ii)=>row(it,si,ii)).join('')}${s.need<s.items.length?`<p class="ex usn">${s.need} tanesini bitirmen yeterli; diğerleri isteğe bağlı.</p>`:''}</details>`;
 M.innerHTML=`<div class="gbar"><button class="lnk" id="unb">‹ Üniteler</button><span class="ex">${u.l} · Ünite ${u.n} / ${a.length}</span></div>
 <div class="card left unh" style="--h:${(UNITS.indexOf(u)*47)%360}"><div class="unhd"><div class="unring" style="--p:${Math.round(d/n*100)}"><span>${u.ic}</span></div><div><p class="big sm" style="margin:0">${esc(u.tt)}</p><p class="ex" style="margin:2px 0 0">${esc(u.t)} · ${d} / ${n} temel adım${ok?' · ✓ geçildi':''}</p></div></div>
 ${nx?`<div class="unnx"><small>Sıradaki</small><b>${nx.s.ic} ${esc(nx.it.lab)}</b><span class="ex">${esc(nx.s.t)}${nx.it.sub?' · '+esc(nx.it.sub):''} · ~${nx.it.m||5} dk</span><button class="btn" id="ungo">${nx.s.k==='ut'?'Teste gir':'Başla'}</button></div>`
 :ok?`<div class="unnx done"><b>🎉 Bu üniteyi tamamladın</b>${nu?`<button class="btn" id="unnx">Sonraki ünite: ${esc(nu.tt)}</button>`:`<span class="ex">Bu seviyenin bütün ünitelerini bitirdin; seviye sonu testine girebilirsin.</span><button class="btn" onclick="go('seviye')">Seviye planına git</button>`}</div>`:''}</div>
 <details class="card left uncdw"><summary><b>🎯 Bu ünitenin hedefleri</b><span class="ex">${cy} / ${u.cd.length} yapabiliyorum</span></summary><ul class="uncd">${u.cd.map((c,i)=>{const v=cd[i]||0;return `<li><button class="uncb v${v}" data-ucd="${i}"><span>${['○','◐','✓'][v]}</span><span>${esc(c)}</span><small>${['henüz değil','biraz','yapabiliyorum'][v]}</small></button></li>`}).join('')}</ul><p class="ex" style="margin:0">Maddelere dokunarak kendini değerlendir.</p></details>
 <p class="gal unsec">Temel adımlar</p>${core.map(step).join('')}
 ${ext.length?`<details class="unex"><summary><span><b>Ek çalışmalar</b> <small class="ex">isteğe bağlı</small></span><span class="ex">${ed} / ${ext.length}</span></summary><p class="ex" style="margin:4px 2px 8px">Üniteyi geçmek için gerekmez; konuyu pekiştirmek ve sınava hazırlanmak için.</p>${ext.map(step).join('')}</details>`:''}`;
 $('#unb').onclick=()=>{S.unl=u.l;go('uniteler')};const g=$('#ungo');if(g)g.onclick=()=>nx.it.open();const x=$('#unnx');if(x)x.onclick=()=>{UX={id:nu.id};unite()};
 document.querySelectorAll('[data-ucd]').forEach(b=>b.onclick=()=>{const c=unCD(u.id),i=+b.dataset.ucd;c[i]=((c[i]||0)+1)%3;save();unite();const w=document.querySelector('.uncdw');if(w)w.open=true});
