function match(){const f=filt();
if(!f.length){$('#main').innerHTML='<div class="card"><p>Bu filtrede kelime yok.</p></div>';return}
const pgs=[];for(let i=0;i<f.length;i+=10)pgs.push(f.slice(i,i+10));
if(pgs.length>1&&pgs[pgs.length-1].length<5){const l=pgs.pop();pgs[pgs.length-1]=pgs[pgs.length-1].concat(l)}
const pg=pgs.length;S.mp=Math.min(Math.max(S.mp||0,0),pg-1);
const ws=pgs[S.mp],rev=dirRev(),L=shuf(ws),R=shuf(ws);let sel=null,left=ws.length;
$('#cnt').textContent=lbl()+': sayfa '+(S.mp+1)+' / '+pg+', '+ws.length+' kelime';
const lb=(w,en)=>en?`${esc(w.w)} <small>${AB[w.p]||esc(w.p)}</small>`:esc(w.tr);
$('#main').innerHTML=`<div class="mt"><div>${L.map((w,i)=>`<button class="opt" data-s="l" data-i="${i}">${lb(w,!rev)}</button>`).join('')}</div><div>${R.map((w,i)=>`<button class="opt" data-s="r" data-i="${i}">${lb(w,rev)}</button>`).join('')}</div></div><div id="fb"></div>${navRow()}`;
document.querySelectorAll('.opt').forEach(b=>b.onclick=()=>{
if(b.dataset.s==='l'){document.querySelectorAll('[data-s=l]').forEach(x=>x.classList.remove('sel'));sel=b;b.classList.add('sel');return}
if(!sel)return;const a=L[sel.dataset.i],c=R[b.dataset.i];
if(a===c||a.tr===c.tr){[sel,b].forEach(x=>{x.disabled=true;x.classList.add('good');x.classList.remove('sel')});award(a,1);sel=null;if(!--left)$('#fb').innerHTML='<p class="vd good">Sayfa tamamlandı, Sonraki ile devam et.</p>'}
else{b.classList.add('bad');setTimeout(()=>b.classList.remove('bad'),500);award(a,0)}});
const mv=d=>{S.mp=(S.mp+d+pg)%pg;save();match()};
$('#pv').onclick=()=>mv(-1);$('#nt').onclick=()=>mv(1)}
const nz=s=>String(s).toLocaleLowerCase('tr').replace(/[âä]/g,'a').replace(/[îı]/g,'i').replace(/[ôö]/g,'o').replace(/[ûü]/g,'u').replace(/ç/g,'c').replace(/ğ/g,'g').replace(/ş/g,'s').replace(/\(.*?\)/g,' ').replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
function dist(a,b){const d=[];for(let i=0;i<=a.length;i++)d[i]=[i];for(let j=1;j<=b.length;j++)d[0][j]=j;
for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++){d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));if(i>1&&j>1&&a[i-1]===b[j-2]&&a[i-2]===b[j-1])d[i][j]=Math.min(d[i][j],d[i-2][j-2]+1)}return d[a.length][b.length]}
function cands(w,rev){const l=rev?[w.w]:w.tr.split(/[,;\/]/),out=new Set();
l.forEach(x=>{const n=nz(x);if(!n)return;out.add(n);if(rev){out.add('to '+n)}else out.add(n.replace(/ (mak|mek)$/,''))});
(S.alt[key(w)+(rev?'r':'t')]||[]).forEach(x=>out.add(x));return [...out]}
function judge(inp,c){const n=nz(inp);if(!n)return null;if(c.includes(n))return 'ok';
for(const x of c){const t=x.length<=3?0:x.length<=7?1:2;if(t&&dist(n,x)<=t)return 'near'}return 'no'}
function typing(q){if(!q){const nw=nextWord();if(!nw)return finished();q={w:nw,rev:dirRev()};H.push(q);hi=H.length-1}
const w=q.w,rev=q.rev,c=cands(w,rev),shown=rev?w.w:w.tr;
const DH=`<button class="spk big2" data-say="${esc(w.w)}" aria-label="Dinle">🔊</button><div><button class="lnk" data-say="${esc(w.w)}" data-slow="1">🐢 Yavaş dinle</button></div>`;
const head=q.au?DH+'<div class="pos">Duyduğun kelimeyi İngilizce yaz</div>':rev?`<div class="big sm">${esc(w.tr)}</div><div class="pos">İngilizcesini yaz (${esc(w.p)})</div>`:`<div class="big">${esc(w.w)} ${SP(w.w)}</div><div class="pos">${esc(w.p)}, Türkçesini yaz</div>`;
$('#main').innerHTML=`<div class="card">${bd(w)}${head}</div><input id="in" class="inp" autocomplete="off" autocapitalize="none" autocorrect="off" spellcheck="false" placeholder="Cevabını yaz"><p class="hp" id="hp"></p><button class="btn" id="chk" style="margin-top:10px">Kontrol et</button><div class="row" id="hr" style="margin-top:8px"><button class="btn no" id="hn">İpucu</button><button class="btn no" id="sa">Cevabı göster</button></div><div id="fb"></div>${navRow()}`;
const inp=$('#in');inp.focus();let done=false,hl=0;const ans=rev?w.w:w.tr.split(/[,;\/]/)[0].trim(),nL=ans.replace(/\s/g,'').length;
$('#hn').onclick=()=>{hl++;if(hl>=nL){$('#sa').click();return}let c=0;$('#hp').textContent=[...ans].map(ch=>ch===' '?'  ':(c++<hl?ch:'_')).join('');inp.focus()};
$('#sa').onclick=()=>{if(done)return;done=true;inp.disabled=true;$('#chk').hidden=true;$('#hr').hidden=true;$('#hp').textContent='';award(w,0);sayA(w);$('#fb').innerHTML=`<p class="vd bad">Cevap: <b>${esc(shown)}</b></p><p class="ex">Bu kelime birkaç soru sonra tekrar gelecek.</p>${rv(w)}`};
const check=()=>{if(done)return;const r=judge(inp.value,c);if(!r)return;done=true;inp.disabled=true;$('#chk').hidden=true;$('#hr').hidden=true;$('#hp').textContent='';
if(r!=='no'){award(w,1);sayA(w);inp.classList.add(r==='ok'?'ok':'near');$('#fb').innerHTML=`<p class="vd good">${r==='ok'?'Doğru!':'Doğru sayıldı, küçük bir yazım farkı var.'}</p><p class="se">Tam yazım: ${esc(shown)}</p>${rv(w)}`}
else{inp.classList.add('bad');sayA(w);pendF=()=>award(w,0);$('#fb').innerHTML=`<p class="vd bad">Yanlış. Kabul edilen cevap: <b>${esc(shown)}</b></p>${rv(w)}<button class="btn no" id="ov">Aslında doğruydu</button>`;
$('#ov').onclick=()=>{pendF=null;const k=key(w)+(rev?'r':'t');(S.alt[k]=S.alt[k]||[]).push(nz(inp.value));award(w,1);$('#ov').hidden=true;$('#fb').insertAdjacentHTML('afterbegin','<p>Kaydedildi, bundan sonra doğru sayılır.</p>')}}};
$('#chk').onclick=check;inp.onkeydown=e=>{if(e.key==='Enter')check()};wire(R(q.au?listen:typing));if(q.au)setTimeout(()=>say(w.w),300);else if(!rev)sayQ(w)}
function add(){
$('#main').innerHTML=`<div class="card left"><p><b>${words.length}</b> kelime yüklü.</p><p class="ex">Yeni kelimeleri JSON olarak yapıştır. Biçim: [{"w":"","p":"noun","en":"","tr":"","ex":"","exTr":""}]</p><textarea id="ta" rows="7"></textarea><button class="btn" id="ad">Kelimeleri ekle</button><p id="fb" class="ex"></p></div>`;
$('#ad').onclick=()=>{try{const a=JSON.parse($('#ta').value);if(!Array.isArray(a))throw 0;
const ok=a.filter(x=>x&&x.w&&x.p&&x.en&&x.tr&&x.ex&&x.exTr).map(x=>({w:String(x.w),p:String(x.p),en:String(x.en),tr:String(x.tr),ex:String(x.ex),exTr:String(x.exTr),c:Array.isArray(x.c)?x.c.map(String):[],l:['A1','A2','B1','B2'].includes(x.l)?x.l:'A2',t:String(x.t||'Genel')}));
const have=new Set(words.map(key)),nw=ok.filter(x=>!have.has(key(x)));words=words.concat(nw);
let old=[];try{old=JSON.parse(localStorage.getItem('kvx'))||[]}catch(e){}
try{localStorage.setItem('kvx',JSON.stringify(old.concat(nw)))}catch(e){}
$('#fb').textContent=nw.length+' yeni kelime eklendi.';fopts()}catch(e){$('#fb').textContent='JSON okunamadı. Biçimi kontrol et.'}}}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>go(b.dataset.m));
let lastAct=Date.now(),tk=0;['pointerdown','keydown'].forEach(e=>addEventListener(e,()=>lastAct=Date.now()));
setInterval(()=>{if(document.visibilityState==='visible'&&Date.now()-lastAct<6e4){const d=new Date().toDateString();if(S.td!==d){S.td=d;S.tdd=0}S.tt=(S.tt||0)+5;S.tdd=(S.tdd||0)+5;if(++tk%6===0)save()}},5e3);
if(!filt().length){S.f.t='';if(!filt().length)S.f.l=''}
if(['quiz','fill'].includes(S.m))S.m='test';if(['typing','listen'].includes(S.m))S.m='yaz';if(!['card','test','yaz','match'].includes(S.m))S.m='test';
if(S.v!==2){S.v=2;S.started=false;save()}
hud();go('home');
